-- US admission requirements, wave 4 (last 140 schools by program count), official pages, checked 13 Nov 2026. Needs step181.
update schools set admission_info = $q${"ug": "Freshmen with a 3.0 or higher GPA in the required high school courses can apply test optional. Those with a 2.25 or higher GPA need SAT 480 Reading and Writing and 440 Math, or ACT 17 in English and Math.", "pg": "Needs a statement of purpose of 550 to 600 words, a CV, three recommendation letters and official transcripts from every school attended.", "english": "TOEFL iBT minimum 69 (79 recommended). Graduate applicants can also use paper TOEFL 523 or IELTS 6. Scores expire after two years. Some applicants are exempt.", "how_to_apply": "Apply online. Graduate applicants apply through GradCAS or the university portal. Early applicants get the best scholarship options. The page lists no international scholarships by name.", "deadlines": "Undergraduate: Fall priority December 15, Fall final June 15, Spring November 1, Summer May 1.", "application_fee": "Graduate international fee is $113, non-refundable. Undergraduate fee is not listed.", "documents": "Passport, official transcripts, immunization form, bank statement for the I-20 and scholarship award letter if any.", "fees_link": "https://www.fvsu.edu/admissions/ctr-international", "sources": ["https://www.fvsu.edu/admissions/ctr-international"]}$q$::jsonb, admission_link = $q$https://www.fvsu.edu/admissions/ctr-international$q$, admission_checked = '2026-11-13' where id = '74fdf75b-13d8-48e4-9ff1-db588f40d235' and country = 'United States';
update schools set admission_info = $q${"ug": "Freshman applicants need official transcripts showing at least a 2.0 GPA on a 4.0 scale. SAT or ACT is optional. Students with college work outside the US apply as transfers.", "pg": "Contact the program for graduate criteria. The same English test rules apply to graduate applicants.", "english": "TOEFL iBT 61 (paper 500), IELTS 5.5, Duolingo 85, PTE 43, SAT 1100, ACT 18. WASSCE or WAEC English with a C4 is also accepted. Scores must be less than 3 years old.", "how_to_apply": "Apply through ApplyTexas. After you get your student ID email, submit the F-1 Student Agreement Form and proof of funding in the international student portal. The I-20 is issued after admission.", "deadlines": "Not listed on the pages read. Contact international@tamuv.edu.", "application_fee": "$25, non-refundable.", "documents": "Official transcripts with English translation, English test score, letter of financial sponsorship, bank statements less than 6 months old showing one year of costs, passport copy.", "fees_link": "https://www.tamuv.edu/international/undergraduate-admissions/", "sources": ["http://www.tamuv.edu/international/undergraduate-admissions/freshman-requirements/", "https://www.tamuv.edu/international/apply-to-program/english-proficiency/"]}$q$::jsonb, admission_link = $q$https://www.tamuv.edu/international/apply-to-program/english-proficiency/$q$, admission_checked = '2026-11-13' where id = '7b343b54-684c-47fd-8677-9c70f8214213' and country = 'United States';
update schools set admission_info = $q${"ug": "Send high school and college transcripts to international@northern.edu. Transfers with 24 or more credits need a 2.0 college GPA and good standing.", "pg": "Graduate requirements are not on the international page. Email international@northern.edu.", "english": "One of: TOEFL iBT 61 to 70 or above, IELTS 5.5, Duolingo 90, SAT 970 or ACT 18.", "how_to_apply": "Apply online. The page lists no current scholarships for new international students. One international scholarship exists for current F-1 students only.", "deadlines": "Not listed on the page read.", "application_fee": "$25, non-refundable.", "documents": "Passport copy, Declaration of Finances with bank statement, immunization form, transcripts with English translation, health insurance.", "fees_link": "https://northern.edu/admissions/international-students", "sources": ["https://northern.edu/admissions/international-students"]}$q$::jsonb, admission_link = $q$https://northern.edu/admissions/international-students$q$, admission_checked = '2026-11-13' where id = 'a984f1d7-a799-4334-92d3-5931baf7f305' and country = 'United States';
update schools set admission_info = $q${"ug": "Secondary school graduation with about a 2.5 GPA. Needs 4 years of native language, 3 years of math, 2 years of lab science and 3 years of social science including history.", "pg": "Graduate rules are on a separate Graduate Studies page that was not readable.", "english": "TOEFL iBT 79 (paper 550), IELTS 6.5, PTE 53, Duolingo 105, Cambridge C1 or C2 score 180.", "how_to_apply": "Complete the international online application and send documents to International Programs. A transcript evaluation from WES is required. The page does not mention scholarships for international students.", "deadlines": "Fall: May 1. Spring: October 1.", "application_fee": "Amount not stated. Paid through the Cashier's Office.", "documents": "Test scores, Certificate of Financial Responsibility with family support letters, WES evaluation (document by document for high school, course by course for college).", "fees_link": "https://www.nmt.edu/studentaffairs/intlprograms/intlstudents/", "sources": ["https://www.nmt.edu/studentaffairs/intlprograms/intlstudents/"]}$q$::jsonb, admission_link = $q$https://www.nmt.edu/studentaffairs/intlprograms/intlstudents/$q$, admission_checked = '2026-11-13' where id = '07a1c605-255a-47e1-b3fe-2c5c1f726664' and country = 'United States';
update schools set admission_info = $q${"ug": "Official transcripts evaluated course by course by WES, ECE or TEC. Proof of ability to pay $33,830 for 2026 to 2027 is required.", "pg": "Graduate details are on the MBA page, which was not read.", "english": "Any one: TOEFL iBT 61 (paper 500), IELTS 6.0, PTE 44, Duolingo 95, SAT EBRW 510, ACT 20, AP English Language 3, or ELS level 112.", "how_to_apply": "Apply online for free. The page links to incoming student scholarships but gives no international amounts.", "deadlines": "Not listed on the page read.", "application_fee": "Free.", "documents": "Evaluated transcripts, declaration of finances with bank statement or sponsor letter, passport valid 6 months beyond stay, GEOBlue insurance.", "fees_link": "https://www.lssu.edu/admissions/international-students/", "sources": ["https://www.lssu.edu/admissions/international-students/"]}$q$::jsonb, admission_link = $q$https://www.lssu.edu/admissions/international-students/$q$, admission_checked = '2026-11-13' where id = '81faba1e-cdd4-4226-8feb-fbf76d9a42cb' and country = 'United States';
update schools set admission_info = $q${"ug": "Online undergraduate application, official records with course by course evaluation (WES, InCred, Ucredo or SpanTran), and proof of first-year support with a $32,400 sponsor affidavit.", "pg": "Graduate requirements are on a separate page that was not read.", "english": "TOEFL iBT 61, IELTS 5.5, Duolingo 95, SAT EBRW 480, ACT English 18, Pearson 50. Waived for a C or better in English 1101 from an accredited US school.", "how_to_apply": "Apply online, then request housing. Two named scholarships exist for international students.", "deadlines": "Fall: July 1. Spring: November 1.", "application_fee": "Not stated.", "documents": "Color passport copy, health insurance, immunization record, financial proof in USD dated within 3 months.", "fees_link": "https://www.fairmontstate.edu/epics/admissions/", "sources": ["https://www.fairmontstate.edu/epics/admissions/", "https://fairmontstate.edu/epics/admissions/international-student-scholarship.aspx"]}$q$::jsonb, admission_link = $q$https://www.fairmontstate.edu/epics/admissions/$q$, admission_checked = '2026-11-13' where id = 'cd65b23e-1060-4779-a690-3a9dbd62544a' and country = 'United States';
update schools set admission_info = $q${"ug": "Freshmen need a 2.75 high school GPA and an SAT, ACT or Accuplacer math score. Transfers need 2.75 in high school and college.", "pg": "Graduate requirements are not on the page read. Assistantships are given by departments.", "english": "Duolingo 105, IELTS 6.5, PTE 56 or TOEFL iBT 79. Exempt with SAT English 500 or ACT English 18.", "how_to_apply": "Apply online. The university says it has no scholarships specifically for international students. First-year students may get merit scholarships if admitted early.", "deadlines": "Official transcripts due August 15 (Fall) and December 15 (Spring). Admit by December 1 (Fall) or November 1 (Spring) for merit consideration.", "application_fee": "Not stated.", "documents": "High school and college transcripts, SAT or ACT scores sent by the testing agency.", "fees_link": "https://www.sdsmt.edu/admissions-aid/international-students/undergraduate-admissions.html", "sources": ["https://www.sdsmt.edu/admissions-aid/international-students/undergraduate-admissions.html"]}$q$::jsonb, admission_link = $q$https://www.sdsmt.edu/admissions-aid/international-students/undergraduate-admissions.html$q$, admission_checked = '2026-11-13' where id = '08bd8cdb-fb60-4f91-82d4-9a47df65f353' and country = 'United States';
update schools set admission_info = $q${"ug": "Open to transfer students only: at least 30 transferable college credits and a 2.0 GPA.", "pg": "Graduate: 3.0 GPA for full admission, or 2.5 to 2.99 for conditional admission. GRE and GMAT are waived.", "english": "Undergraduate: TOEFL iBT 69 or IELTS 6. Graduate: TOEFL iBT 80 or IELTS 6.", "how_to_apply": "Submit the international application and a course by course transcript evaluation, then request your I-20 after admission. Scholarships are not listed on the page.", "deadlines": "Not listed on the page read.", "application_fee": "Not listed.", "documents": "Transcript evaluation from NACES or AICE member, official US transcripts, health insurance.", "fees_link": "https://tamuct.edu/international/index.html", "sources": ["https://tamuct.edu/international/index.html"]}$q$::jsonb, admission_link = $q$https://tamuct.edu/international/index.html$q$, admission_checked = '2026-11-13' where id = '2e506f11-c334-41a8-b705-e62f36d0cd60' and country = 'United States';
update schools set admission_info = $q${"ug": "Undergraduate page could not be read. Contact the Office of International Studies.", "pg": "Needs the international graduate application, official transcripts, an AACRAO or ECE course by course evaluation, a letter of intent, a resume, three recommendation letters and a passport copy. GRE only if the program asks.", "english": "Graduate: TOEFL 79, IELTS 6.5, Duolingo 100, iTEP 3.5 to 3.9 or PTE 58. Waived for degrees from the US or listed English-speaking countries.", "how_to_apply": "Apply with the international application and fee. Provisional admission through the English program is possible.", "deadlines": "Graduate: Fall June 1, Spring October 1, Summer February 1.", "application_fee": "Graduate: $40, non-refundable.", "documents": "Financial statement with a bank letter for one year, health history form signed by a physician.", "fees_link": "https://catalog.msubillings.edu/graduate/graduate-programs-admissions/", "sources": ["https://catalog.msubillings.edu/graduate/graduate-programs-admissions/"]}$q$::jsonb, admission_link = $q$https://catalog.msubillings.edu/graduate/graduate-programs-admissions/$q$, admission_checked = '2026-11-13' where id = '3d11f642-9827-453b-ac3b-7d7ecf53036d' and country = 'United States';
update schools set admission_info = $q${"ug": "Needs the equivalent of a US high school diploma, good standing at home, and coursework in English, history, math and science.", "pg": "Graduate requirements are not covered on the page read.", "english": "TOEFL scores are required but the page gives no minimum.", "how_to_apply": "Apply with official transcripts and TOEFL sent directly. The university gives no financial aid to international undergraduates, but says some scholarships exist for qualified students without naming them.", "deadlines": "Fall: July 1. Spring: November 1. Summer: April 1.", "application_fee": "Not listed.", "documents": "Official transcripts, TOEFL, proof of finances, health insurance, health history form and TB test.", "fees_link": "https://www.fmarion.edu/admissions/admissions-international-student-checklist/", "sources": ["https://www.fmarion.edu/admissions/admissions-international-student-checklist/"]}$q$::jsonb, admission_link = $q$https://www.fmarion.edu/admissions/admissions-international-student-checklist/$q$, admission_checked = '2026-11-13' where id = '7c9a5495-9def-4895-a146-6ef3b8655b6a' and country = 'United States';
update schools set admission_info = $q${"ug": "Needs transcripts evaluated by a NACES service (TEC recommended), a handwritten two page essay on educational intent, a financial certification form and a passport copy.", "english": "Accepts SAT, ACT, TOEFL, IELTS or Duolingo. The page gives no minimum scores. Submit only one test.", "how_to_apply": "Apply online and send documents to the international admissions counselor. An International Student Award of $2,000 is available.", "deadlines": "Materials due June 1 (Fall) and October 1 (Spring).", "application_fee": "Not listed.", "documents": "Passport page, essay, financial certification form, transcripts, evaluated transcripts, test scores.", "fees_link": "https://www.wsc.edu/international-students", "sources": ["https://www.wsc.edu/international-students/international-student-admissions-process", "https://www.wsc.edu/scholarships/international-student-scholarships"]}$q$::jsonb, admission_link = $q$https://www.wsc.edu/international-students$q$, admission_checked = '2026-11-13' where id = 'b4828ebf-1b7c-4321-8d6d-4be0097ea7ac' and country = 'United States';
update schools set admission_info = $q${"ug": "Transcripts must be evaluated by WES or another NACES service. High school needs document by document, college needs course by course. SAT or ACT is waived with a 3.0 core GPA through Summer 2027.", "pg": "Graduate international page exists but was not read.", "english": "TOEFL iBT 69 (79 recommended), IELTS 6.0, PTE 58, MET 59, Cambridge 169 to 177. Scores must come from the testing agency.", "how_to_apply": "Apply online. International students need a Financial Verification Form. The I-20 is issued after acceptance.", "deadlines": "Fall: July 15. Spring: November 15. No Summer for visa students.", "application_fee": "$40, non-refundable.", "documents": "Evaluated transcripts, English test score, Financial Verification Form with sworn bank letter, immunization forms.", "fees_link": "https://www.clayton.edu/admissions/undergrad/international.php", "sources": ["https://www.clayton.edu/admissions/undergrad/international.php"]}$q$::jsonb, admission_link = $q$https://www.clayton.edu/admissions/undergrad/international.php$q$, admission_checked = '2026-11-13' where id = '09ee7518-1b2a-4908-a8f8-d603bcf5ec71' and country = 'United States';
update schools set admission_info = $q${"ug": "Freshmen need ACT 19 or SAT 980 (SAT currently waived). Needs high school transcripts, diploma and passport copy.", "pg": "Needs official transcripts from all undergraduate and graduate study in good standing. No entrance exam listed.", "english": "TOEFL iBT, IELTS, PTE, LanguageCert Academic accepted. Minimum scores are on a separate page.", "how_to_apply": "Apply online. A $3,000 international student deposit is required and applied to tuition. The university says it offers international scholarships but gives no details.", "deadlines": "Fall: June 1. Spring: October 1. Summer: March 1.", "application_fee": "Not listed. Waived during a Free Application Week in October.", "documents": "Passport valid 6 months past start, transcripts, bank statements, Statement of Financial Support, immunization forms.", "fees_link": "https://www.uwa.edu/admissions/international-students/application-information/", "sources": ["https://www.uwa.edu/admissions/international-students/application-information/"]}$q$::jsonb, admission_link = $q$https://www.uwa.edu/admissions/international-students/application-information/$q$, admission_checked = '2026-11-13' where id = '366fc1fc-9957-4464-9664-e8cebe8464a3' and country = 'United States';
update schools set admission_info = $q${"ug": "Official secondary transcripts with a course by course GPA evaluation from a NACES member. SAT or ACT is optional. A 200 to 500 word essay is optional.", "pg": "The page does not cover graduate admission. Contact International Programs.", "english": "TOEFL iBT 61 (paper 500), IELTS 5.5, Duolingo 85 or PTE 44. Exemptions exist for English-medium schooling.", "how_to_apply": "Apply online. Degree-seeking international students are automatically considered for merit scholarships.", "deadlines": "Fall, Spring and Summer deadlines exist but dates were not shown in the page text.", "application_fee": "$40, non-refundable.", "documents": "Transcripts, GPA evaluation, English scores, Declaration and Certification of Finances.", "fees_link": "https://www.fortlewis.edu/admission/international-students", "sources": ["https://www.fortlewis.edu/admission/international-students", "https://www.fortlewis.edu/tuition-aid/scholarships/scholarships-home/international"]}$q$::jsonb, admission_link = $q$https://www.fortlewis.edu/admission/international-students$q$, admission_checked = '2026-11-13' where id = '7becc06d-5bef-4734-821b-18910d86ee6d' and country = 'United States';
update schools set admission_info = $q${"ug": "Official transcripts evaluated document by document (high school) or course by course (college), with notarized English translations. SAT or ACT is needed only in some cases.", "pg": "Graduate applicants also need three recommendation letters.", "english": "TOEFL iBT 61 (paper 500), IELTS 6, Duolingo 100.", "how_to_apply": "Submit the application with documents. The page lists no international scholarships.", "deadlines": "Fall: May 15. Spring: December 15.", "application_fee": "Graduate: $50, non-refundable. Undergraduate fee not listed.", "documents": "Transcripts, evaluation by TEC, WES or Josef Silny, English proficiency proof.", "fees_link": "https://www.coppin.edu/international-admissions", "sources": ["https://www.coppin.edu/international-admissions"]}$q$::jsonb, admission_link = $q$https://www.coppin.edu/international-admissions$q$, admission_checked = '2026-11-13' where id = 'c305cf05-3189-4614-a619-c81f72ed399d' and country = 'United States';
update schools set admission_info = $q${"ug": "Common App or SUNY application, secondary transcripts, one teacher recommendation, a one page personal statement and a passport copy. SAT or ACT is optional.", "pg": "Graduate details are on a separate Geneseo graduate page that was not read.", "english": "TOEFL iBT 72, IELTS 6.0 (no part below 5.5), PTE 58, Duolingo 105. WASSCE English with a C or better is accepted.", "how_to_apply": "Apply with the Common App or SUNY application. Use code INTLFREE to waive the fee. Merit scholarships up to $10,000 a year are considered automatically.", "deadlines": "Not listed on the page read.", "application_fee": "Waived for international students with code INTLFREE.", "documents": "Transcripts with English translation, recommendation, personal statement, passport copy, financial statement before I-20.", "fees_link": "https://www.geneseo.edu/international/cost-scholarships/", "sources": ["https://www.geneseo.edu/admissions/how-apply-geneseo-international-student/", "https://www.geneseo.edu/international/cost-scholarships/"]}$q$::jsonb, admission_link = $q$https://www.geneseo.edu/international/cost-scholarships/$q$, admission_checked = '2026-11-13' where id = 'c310c97f-4c2b-4386-bb4c-4240206e8bf4' and country = 'United States';
