update schools set admission_info = $q${"ug": "Apply through CUNY with secondary transcripts and diplomas with English translation. SAT or ACT is recommended for non-native English applicants.", "pg": "Needs a course by course evaluation from a NACES member and official transcripts.", "english": "Undergraduate: TOEFL iBT 61, IELTS 6.0, Duolingo 90, PTE 44. Graduate: TOEFL 79 to 80, IELTS 7.0, Duolingo 105, PTE 53.", "how_to_apply": "Apply through CUNY. An I-20 is requested after acceptance. No international scholarships are on the pages read.", "deadlines": "Undergraduate: Fall February 1 (priority), Spring September 15. Graduate: Fall April 1, Spring November 1.", "application_fee": "Undergraduate: $65 freshman, $70 transfer. Graduate not listed.", "documents": "Transcripts, diplomas, translations, test scores, credential evaluation (graduate).", "fees_link": "https://www.jjay.cuny.edu/admissions/undergraduate-admissions/apply/international-student-application", "sources": ["https://www.jjay.cuny.edu/admissions/undergraduate-admissions/apply/international-student-application", "https://www.jjay.cuny.edu/admissions/graduate-admissions/international-graduate-students"]}$q$::jsonb, admission_link = $q$https://www.jjay.cuny.edu/admissions/undergraduate-admissions/apply/international-student-application$q$, admission_checked = '2026-11-13' where id = 'adec4f43-0e04-473f-ad92-f3a9a1b73321' and country = 'United States';
update schools set admission_info = $q${"ug": "Official secondary and college transcripts with a course-by-course evaluation from a NACES member, a SUNY essay written in English, and proof of English skills. Dental Hygiene and Nursing need U.S. citizenship or permanent residency, except the online RN to BS program.", "pg": "The page does not split graduate rules from undergraduate rules. Check with the international office for graduate programs.", "english": "TOEFL iBT 74, IELTS 6.0, PTE 53, Duolingo 105, or SAT Evidence-Based Reading 400. A C+ or better in a college writing course at an accredited U.S. college also counts. Scores must be less than two years old.", "how_to_apply": "Apply online through the Apply Now link on the international page. You may apply to only one program. The school says financial aid and scholarships are not available to international students.", "deadlines": "June 1 for Fall and November 1 for Spring.", "application_fee": "$50 USD, paid online.", "documents": "Transcripts with certified translation, NACES course-by-course evaluation, SUNY essay, passport copies, home address, English test report, and proof of funds ($40,000 on campus or $28,000 off campus with a local sponsor) for the I-20.", "fees_link": "https://www.farmingdale.edu/international-education/how-to-apply.shtml", "sources": ["https://www.farmingdale.edu/international-education/how-to-apply.shtml"]}$q$::jsonb, admission_link = $q$https://www.farmingdale.edu/international-education/how-to-apply.shtml$q$, admission_checked = '2026-11-13' where id = 'f037d6b6-20e4-4c17-8eec-2aefcd9d9f92' and country = 'United States';
update schools set admission_info = $q${"ug": "Must be 18 by enrollment. Submit the international application, a Statement of Understanding, a passport copy, a Financial Guarantee Form with bank statement, and transcripts evaluated by a NACES company. Immunization and meningitis forms are also needed.", "pg": "Same general steps as undergraduate, plus the GRE or Miller Analogies Test. Apply through the International Office first, then the Graduate Office. Programs listed: MA American Studies, M.Ed., and MA Counseling Psychology.", "english": "Undergraduate: TOEFL 61 or IELTS 5.5 (the school's own pages show some conflicting numbers, so confirm). Graduate: TOEFL 79 or IELTS 6.5. SAT 1020 or ACT 20 is accepted only for students from English-primary countries.", "how_to_apply": "Complete the online International Student Application, then send the listed documents to the International Office. International students are not eligible for Oklahoma state or federal aid.", "deadlines": "Fall: July 15. Spring: December 10. No summer admission for international students.", "application_fee": "Not listed on the page.", "documents": "Application, Statement of Understanding, Financial Guarantee Form and bank letters in USD, NACES transcript evaluation (SpanTran, GCE, WES, or Josef Silny), passport copy, immunization and meningitis forms.", "fees_link": "https://www.nwosu.edu/apply-for-admission/international-students", "sources": ["https://www.nwosu.edu/apply-for-admission/international-students", "https://www.nwosu.edu/paying-for-college/international-student-costs"]}$q$::jsonb, admission_link = $q$https://www.nwosu.edu/apply-for-admission/international-students$q$, admission_checked = '2026-11-13' where id = '0dc3269c-c33b-4464-8860-f1b9307fa40c' and country = 'United States';
update schools set admission_info = $q${"ug": "Holistic review. Official high school transcript in English sent directly from the school with an official seal. Transfer applicants need official transcripts from every college, with a NACES or AACRAO course-by-course evaluation for non-U.S. work.", "english": "Required if English is not your first language: TOEFL iBT 79, IELTS 6.0, or Duolingo 105. Meeting the score does not guarantee admission.", "how_to_apply": "Apply as an international first-year student. After you pay the enrollment deposit, the international office contacts you for your I-20 details. The international page lists no scholarships made only for international students.", "deadlines": "Fall: June 1. Spring: October 1.", "application_fee": "Not listed on the page.", "documents": "Official high school transcript (sealed or certified, not emailed or faxed by the student), English test score, and I-20 information after the deposit.", "fees_link": "https://www.western.edu/admissions-aid/admissions/application-requirements/international-students/international-first-time-freshmen/", "sources": ["https://www.western.edu/admissions-aid/admissions/application-requirements/international-students/international-first-time-freshmen/"]}$q$::jsonb, admission_link = $q$https://www.western.edu/admissions-aid/admissions/application-requirements/international-students/international-first-time-freshmen/$q$, admission_checked = '2026-11-13' where id = '48fac00a-7b7c-49c0-be49-3ca2675131c8' and country = 'United States';
update schools set admission_info = $q${"ug": "Official SAT or ACT scores unless approved for the test-optional route (fall first-year, 2.5 GPA). High school transcripts with a seal or signature, with certified English translation. Official college transcripts if you have fewer than 30 transferable hours.", "english": "TOEFL iBT 69 or IELTS 6.0. SAT, ACT, and TOEFL Home Edition are also accepted as proof. Students with four years of U.S. high school are exempt.", "how_to_apply": "Apply online through Future Tiger and pay the fee. Also submit the International Student Supplemental Application and a sponsor bank letter. The page lists no scholarships for international students; see the general scholarships page.", "deadlines": "Fall: June 1. Spring: October 15. Summer: March 1.", "application_fee": "$20, non-refundable.", "documents": "Application, test scores, sealed high school transcript, English proof, supplemental international form and checklist, and letter from your sponsor's bank.", "fees_link": "https://Savannahstate.edu/undergraduate/international-tigers.shtml", "sources": ["https://Savannahstate.edu/undergraduate/international-tigers.shtml"]}$q$::jsonb, admission_link = $q$https://Savannahstate.edu/undergraduate/international-tigers.shtml$q$, admission_checked = '2026-11-13' where id = 'cf079efe-03d8-43a0-8d38-e60aea0fffa9' and country = 'United States';
update schools set admission_info = $q${"ug": "First-year: 2.5 GPA on a 4.0 scale for years 10 to 12, English proficiency, and living on campus in the first year. Transfers need a 2.0 college GPA and set math and writing courses.", "pg": "A U.S. bachelor's degree equivalent with a 2.75 GPA (overall or last 60 units), good standing, and approval of the program committee. MBA needs two years of full-time work. GRE or GMAT is waived for MS Computer Science, MS Math, and MS Biotechnology.", "english": "Undergraduate: TOEFL iBT 61, IELTS 6.0, PTE 46, or Duolingo 95. Graduate: TOEFL iBT 80, IELTS 6.5, PTE 56, or Duolingo 105. Waived after three years of high school in a listed English-speaking country.", "how_to_apply": "Apply through Cal State Apply. After admission, meet the international office on Zoom and send the financial affidavit and bank statement for your I-20. The page does not mention scholarships for international students.", "deadlines": "Undergraduate Fall 2026: May 4, 2026. Spring 2027: August 31, 2026. Graduate Fall 2027: June 1, 2027. Some graduate dates on the page look like typos, so confirm.", "application_fee": "$70 for undergraduate and graduate applications.", "documents": "Transcripts, passport copy, financial affidavit, and bank statement of at least $44,100 for undergraduates. Graduates also send a 500 to 600 word statement, resume, two recommendation letters, and a $250 deposit after admission.", "fees_link": "https://www.csuci.edu/international/admissions/undergraduate.htm", "sources": ["https://www.csuci.edu/international/admissions/undergraduate.htm", "https://www.csuci.edu/international/admissions/graduate.htm"]}$q$::jsonb, admission_link = $q$https://www.csuci.edu/international/admissions/undergraduate.htm$q$, admission_checked = '2026-11-13' where id = 'e4d246c8-160a-4456-9903-a690fe3e0c06' and country = 'United States';
update schools set admission_info = $q${"ug": "Secondary school records professionally translated into English. Students from Ghana, Nigeria, Sierra Leone, The Gambia, or Liberia must submit WAEC records. SAT or ACT is not needed if you are 21 or older or have 24 college credits.", "pg": "Official transcripts from every school with a course-by-course evaluation (WES, ECE, or TEC) and a bachelor's from a regionally accredited school. Only the MBA and the MS in Behavioral Sciences (General Psychology) are open to F-1 students. MBA needs a 3.0 GPA or a qualifying GMAT or GRE.", "english": "Undergraduate: TOEFL iBT 61, IELTS 5.5, PTE 44, or iTEP 3.5. Graduate: TOEFL iBT 79, IELTS 6.5, PTE 53, or iTEP 4.0. TOEFL Essentials is not accepted. Scores are valid two years.", "how_to_apply": "Apply online and pay the fee. Send an Affidavit of Financial Support and bank statements covering first-year costs. The school says financial aid and campus jobs cannot be guaranteed.", "deadlines": "Undergraduate: June for Fall, November for Spring. Graduate: June and November recommended, no hard date.", "application_fee": "$20 USD, non-refundable.", "documents": "Passport copy, translated school records (WAEC for Ghana), evaluated transcripts, Affidavit of Financial Support, and six months of certified bank statements. Add $10,000 for a spouse and $6,000 per child.", "fees_link": "https://www.cameron.edu/admissions/international-student-services/future-international-students/undergraduate/undergraduate-admission-requirements", "sources": ["https://www.cameron.edu/admissions/international-student-services/future-international-students/undergraduate/undergraduate-admission-requirements", "https://www.cameron.edu/admissions/international-student-services/future-international-students/graduate/graduate-admission-requirements"]}$q$::jsonb, admission_link = $q$https://www.cameron.edu/admissions/international-student-services/future-international-students/undergraduate/undergraduate-admission-requirements$q$, admission_checked = '2026-11-13' where id = 'fd0d0c23-1d5f-4b5d-8db1-c289ec9e6b70' and country = 'United States';
update schools set admission_info = $q${"ug": "Secondary and any university transcripts, evaluated by an Oregon Tech approved service and translated into English. A signed financial statement covering one year. Undergraduates must take at least 12 credits per quarter.", "pg": "The page says graduate programs may have different requirements. Check the program page. Graduate students must take at least 9 credits per term.", "english": "TOEFL iBT 68 (paper 520), IELTS 6, or Duolingo 95. ACT 21 or SAT English 580 also work. A waiver may apply if you attended an English-language secondary program or are from an English-speaking country.", "how_to_apply": "Apply online with the fee. After admission, send health records, passport copy, and the Financial Statement of Responsibility with bank statements for your I-20. The page lists no scholarships made only for international students.", "deadlines": "Fall: apply by May 1, materials by June 1. Winter: September 1 and October 1. Spring: December 1 and January 1. Summer: April 1 and May 1.", "application_fee": "$50.", "documents": "Evaluated transcripts, English proof, financial statement with bank documents, passport copy, health records, and proof of major medical insurance.", "fees_link": "https://www.oit.edu/admissions/international-students", "sources": ["https://www.oit.edu/admissions/international-students"]}$q$::jsonb, admission_link = $q$https://www.oit.edu/admissions/international-students$q$, admission_checked = '2026-11-13' where id = '1faf3487-a684-4d6e-af54-40729e8095b1' and country = 'United States';
update schools set admission_info = $q${"ug": "Official secondary records for about grades 9 to 11 plus national exam results, with English translations. Transfers also send college transcripts and an official evaluation of non-U.S. coursework. SAT or ACT is optional.", "english": "TOEFL, IELTS, or Duolingo is usually required but may be waived. The page gives no minimum scores. Check the exam guidelines page.", "how_to_apply": "Complete the International Admission Online Application and send documents to upjadmit@pitt.edu. Applications are reviewed on a rolling basis, with a decision about two weeks after your file is complete.", "deadlines": "Fall: all materials by April 15. Spring: October 15.", "application_fee": "Not listed on the page.", "documents": "Secondary records, English test result, and for transfer students an official evaluation and course catalog or syllabi. Optional: recommendation letters, essay, and AP, IB, or A-Level transcripts.", "fees_link": "https://johnstown.pitt.edu/international-admissions", "sources": ["https://johnstown.pitt.edu/international-admissions"]}$q$::jsonb, admission_link = $q$https://johnstown.pitt.edu/international-admissions$q$, admission_checked = '2026-11-13' where id = '5849555f-214a-4bb8-9eb8-b9ed55ba8a1f' and country = 'United States';
update schools set admission_info = $q${"ug": "High school diploma with a B average in lab science, social studies, and math, a course-by-course evaluation (WES or GCE), ACT 21 or SAT 1060 to 1090, immunization certificate, and affidavit of sponsorship with sponsor bank statements.", "english": "TOEFL 525 (computer 195), IELTS 5.5, Duolingo 90, or PTE 42.", "how_to_apply": "Apply online at apply.mvsu.edu. The school website says it is still being restored after a cyber incident, so confirm details with admissions.", "deadlines": "Not listed on the page.", "application_fee": "Not listed on the page.", "documents": "English test, immunization certificate, affidavit of financial sponsorship, sponsor bank statements, evaluated transcript with MVSU listed as recipient.", "fees_link": "https://admissions.mvsu.edu/international-first-year-students", "sources": ["https://admissions.mvsu.edu/international-first-year-students", "https://www.mvsu.edu/international-students"]}$q$::jsonb, admission_link = $q$https://admissions.mvsu.edu/international-first-year-students$q$, admission_checked = '2026-11-13' where id = 'b27a56ba-9acc-479d-b6a0-2070406beb75' and country = 'United States';
update schools set admission_info = $q${"ug": "Official high school transcripts with a course-by-course evaluation (SpanTran or WES) showing a 2.0 GPA. ACT or SAT is not required for admission but is needed for scholarships and placement. Two MMR doses and a TB chest X-ray are required.", "pg": "Four-year bachelor's degree, 3.0 GPA in the field, three recommendation letters, certified transcripts, and GRE or GMAT where the program requires it. On-campus students also need a financial backing letter, health insurance, MMR proof, and TB screening.", "english": "Undergraduate: TOEFL iBT 71, IELTS 5.5, or PTE 48. Graduate: TOEFL iBT 79, IELTS 6.0, or PTE 53 (Nursing and Speech-Language Pathology: iBT 100, IELTS 7.0, PTE 68). Waived for graduates of English-language schools and citizens of English-first countries.", "how_to_apply": "Pay the application fee and send the listed documents. Freshmen are automatically considered for the International Freshman Merit Scholarship at admission.", "deadlines": "Undergraduate: Fall May 1, Spring October 1. Graduate: Fall May 1, Spring October 1, June summer March 1, July summer April 1. Some programs are earlier.", "application_fee": "$100 for undergraduates (applications are not processed without it). Graduate fee not listed.", "documents": "Translated and evaluated transcripts, English test, immunization record, TB X-ray, Financial Backing Form, and health insurance.", "fees_link": "https://www.muw.edu/admissions/international/requirements/", "sources": ["https://www.muw.edu/admissions/international/requirements/", "https://www.muw.edu/graduate/?p=34"]}$q$::jsonb, admission_link = $q$https://www.muw.edu/admissions/international/requirements/$q$, admission_checked = '2026-11-13' where id = 'b75fc3d6-b496-4694-abb5-72741b788c72' and country = 'United States';
update schools set admission_info = $q${"ug": "Official transcripts from every college attended. Non-U.S. college work needs a NACES or AICE course-by-course evaluation. First-year applicants need a document-by-document evaluation of the high school transcript. Declaration and Certification of Finances and passport copy are required.", "pg": "Apply online with a current photo and immunization record. Non-U.S. transcripts must be evaluated by a NACES member such as Josef Silny, WES, or SpanTran. Each program may add its own documents.", "english": "Undergraduate: TOEFL iBT 69 or IELTS 6.5, or SAT 480 reading and 440 math, or ACT 17 English and 17 math. The graduate page does not state English minimums.", "how_to_apply": "Apply online (GaFutures portal for undergraduates). Allow at least four weeks for processing. GSW says it has no scholarships made only for international students, but limited out-of-state tuition waivers exist.", "deadlines": "Not listed on the pages. See the school's Deadlines page.", "application_fee": "Undergraduate: not listed. Graduate: $25, non-refundable.", "documents": "Evaluated transcripts, finance form with stamped bank letter (dated within 12 months), passport copy, and after acceptance health insurance, TB screening, and immunization record.", "fees_link": "https://www.gsw.edu/admissions/undergraduate/international", "sources": ["https://www.gsw.edu/admissions/undergraduate/international", "https://gsw.edu/admissions/graduate/international"]}$q$::jsonb, admission_link = $q$https://www.gsw.edu/admissions/undergraduate/international$q$, admission_checked = '2026-11-13' where id = 'c9cc132c-c246-49ba-9c3c-06b6c95178db' and country = 'United States';
update schools set admission_info = $q${"ug": "Proof of finishing secondary school, official transcripts in English, and a transcript evaluation with GPA from a U.S. agency (WES encouraged). Nigerian students submit WASC. A bank, lender, or sponsor statement must show funds for the program.", "pg": "No GRE, GMAT, or LSAT is required. Send an outside transcript evaluation (WES or SpanTran), accept your offer in writing, and show financial support plus the deposit before the I-20.", "english": "Undergraduate: official SAT, ACT, or TOEFL with a minimum of 71. Graduate: TOEFL iBT 70, IELTS 6.0, or Duolingo 100 (institution code 1368).", "how_to_apply": "Complete the application and send documents. A $3,500 deposit in USD is needed before your I-20 is issued.", "deadlines": "Have a complete application on file three months before the term starts.", "application_fee": "$100 in U.S. funds by money order or cashier's check.", "documents": "Transcripts and evaluation, Declaration of Finances, sponsor or bank statement, and a $3,500 deposit.", "fees_link": "https://www.kysu.edu/policies/files/international-students.pdf", "sources": ["https://www.kysu.edu/policies/files/international-students.pdf", "https://www.kysu.edu/academics/grad-studies/faq-international-students.php"]}$q$::jsonb, admission_link = $q$https://www.kysu.edu/policies/files/international-students.pdf$q$, admission_checked = '2026-11-13' where id = 'e615a3b1-0f9b-4f62-974b-949ced76df0b' and country = 'United States';
update schools set admission_info = $q${"ug": "Five GCE O-level or CXC General passes including English, or a course-by-course evaluation if you do not meet this. Official certificates certified by the Ministry of Education, a Certification of Finances form, and bank letters showing at least one year of funds.", "pg": "Apply through GradCAS (BusinessCAS for business). Send transcripts, a course-by-course evaluation if you studied outside the U.S., personal statement, resume, and recommendation letters, plus the Certification of Finances.", "english": "TOEFL is required if English is not your first language (school code 0879). The pages do not state a minimum score.", "how_to_apply": "Apply online and send supporting documents at least 60 days before the term. The I-20 is issued after admission and the finance form. The undergraduate page does not mention scholarships.", "deadlines": "Undergraduate: Fall June 15, Spring October 15. Graduate: Fall or Summer April 30, Spring October 30.", "application_fee": "Undergraduate: not listed. Graduate: an application fee exists but the amount is not on the page.", "documents": "Certified GCE or CXC certificates, TOEFL, Certification of Finances, bank letters, and a letter on room and board arrangements.", "fees_link": "https://uvi.edu/admissions/undergraduate/international.html", "sources": ["https://uvi.edu/admissions/undergraduate/international.html", "https://uvi.edu/admissions/graduate-admissions/index.html"]}$q$::jsonb, admission_link = $q$https://uvi.edu/admissions/undergraduate/international.html$q$, admission_checked = '2026-11-13' where id = '9da6e252-1879-4682-baf6-505792c53a46' and country = 'United States';
update schools set admission_info = $q${"ug": "Certified original transcripts from all secondary schools with certified English translations and a grading scale explanation, proof of finishing secondary school, Financial Certification Form with bank statements, and passport copy. Transfers need a WES or SpanTran course-by-course evaluation.", "pg": "The international page does not list graduate requirements. It points to a separate Graduate Students page.", "english": "TOEFL 79 or 80, IELTS 6.5, Duolingo 115, or Cambridge C1. IB Diploma holders are exempt.", "how_to_apply": "Apply through the Common Application. Email documents to the international admissions director or upload them in the document portal. Apply by December 1 for priority merit scholarship review.", "deadlines": "No general deadline listed. Priority for merit scholarships: December 1.", "application_fee": "$50 (Common Application).", "documents": "Transcripts with translation, English test, Financial Certification Form, bank statements, and passport copy. Minimum yearly support shown is $43,750.", "fees_link": "https://www.longwood.edu/admissions/international-students/", "sources": ["https://www.longwood.edu/admissions/international-students/"]}$q$::jsonb, admission_link = $q$https://www.longwood.edu/admissions/international-students/$q$, admission_checked = '2026-11-13' where id = 'b1e3e38e-2043-4f54-a9db-aea1d7badb92' and country = 'United States';
update schools set admission_info = $q${"ug": "Online programs. The school does not sponsor student visas. Students outside the U.S. should confirm the program is recognized in their home country. Foreign transcripts must be evaluated by a NACES agency (course-by-course recommended) before full acceptance.", "english": "TOEFL iBT 80 (preferred), IELTS 6.5, or Duolingo 120. A transcript from a school where all courses were taught in English also counts. TOEFL code is 0458.", "how_to_apply": "Apply through the regular online admission process. Applicants already in the U.S. must be permanent residents. Students who want an on-campus experience should apply to UNH Manchester.", "deadlines": "Not listed on the page.", "application_fee": "Not listed on the page.", "documents": "English proof sent directly to admissions and an evaluated foreign transcript sent by the agency.", "fees_link": "https://cps.unh.edu/online/apply-register/apply-now/international-students", "sources": ["https://cps.unh.edu/online/apply-register/apply-now/international-students"]}$q$::jsonb, admission_link = $q$https://cps.unh.edu/online/apply-register/apply-now/international-students$q$, admission_checked = '2026-11-13' where id = '4821c9dd-9807-446d-9edf-8292cceb8bc6' and country = 'United States';
update schools set admission_info = $q${"ug": "First-year: 2.0 weighted GPA with SAT 480 reading and 440 math, or 2.0 unweighted GPA with ACT 17 English or reading and 17 math. Access pathway programs accept a 2.0 GPA. Transfers with under 30 hours also send high school transcripts.", "pg": "Bachelor's degree equivalent with a course-by-course evaluation (WES preferred), Certificate of Finances, and program documents. Transfers from another U.S. school need a Transfer Clearance Form.", "english": "Undergraduate: TOEFL iBT 69, IELTS 6, PTE 53, or SAT and ACT sub-scores. Graduate: TOEFL iBT 69 or IELTS 6. Waived for four years of U.S. high school.", "how_to_apply": "Apply online. Financial proof of $27,600 for the first year is needed for the I-20. The page lists no scholarships made only for international students.", "deadlines": "Undergraduate deadlines not listed. Graduate deadlines not listed.", "application_fee": "Undergraduate: $25. Graduate: non-refundable, amount not listed.", "documents": "Sealed transcripts, evaluated college transcripts, English test, passport scan, immunization records, bank statements dated within six months.", "fees_link": "https://www.asurams.edu/enrollment-management/admissions/international-students.php", "sources": ["https://www.asurams.edu/enrollment-management/admissions/international-students.php", "https://catalog.asurams.edu/graduate/admissions/admissions-international-students/"]}$q$::jsonb, admission_link = $q$https://www.asurams.edu/enrollment-management/admissions/international-students.php$q$, admission_checked = '2026-11-13' where id = '67fcde17-2c73-4b45-b501-1609fe5630fb' and country = 'United States';
update schools set admission_info = $q${"ug": "The undergraduate page says UNT Dallas is not currently SEVP-certified, so it generally cannot admit applicants who are not U.S. citizens or permanent residents, apart from limited Texas law exceptions.", "pg": "Graduate applicants with foreign credentials need an AICE or NACES course-by-course evaluation. The page does not say whether F-1 students can be admitted, so confirm first.", "english": "No English test minimums are listed. Texas Success Initiative rules apply to undergraduates.", "how_to_apply": "Because the school says it is not SEVP-certified, a Ghanaian student needing an F-1 visa should confirm with admissions before applying. It offers no international aid.", "deadlines": "Undergraduate deadlines are the same for all applicants (Fall priority May 1, final August 11). Graduate deadlines vary by program.", "application_fee": "Undergraduate: none. Graduate: $50 per program.", "documents": "Foreign transcripts with English translation and a credential evaluation sent directly by the agency. ApplyTexas application for undergraduates.", "fees_link": "https://undergrad.catalog.untdallas.edu/policies/undergraduate-admissions", "sources": ["https://undergrad.catalog.untdallas.edu/policies/undergraduate-admissions", "https://www.untdallas.edu/gradschool/requirements.php"]}$q$::jsonb, admission_link = $q$https://undergrad.catalog.untdallas.edu/policies/undergraduate-admissions$q$, admission_checked = '2026-11-13' where id = 'ef2d69c4-9268-40ae-bf37-4b6cb3379f0e' and country = 'United States';
update schools set admission_info = $q${"ug": "Official secondary and university transcripts, with non-U.S. records evaluated by Josef Silny & Associates and notarized English translations. A financial sponsorship form with bank verification is required before the I-20.", "english": "TOEFL iBT 61, IELTS 5.5, Duolingo 90, or WAEC grade C or better (within two years). Also accepted: Cambridge CAE C, or ELS Level 112.", "how_to_apply": "Submit the application with all documents. The I-20 is issued only after financial forms are received. The school says it cannot guarantee any full tuition scholarship, and international students cannot get federal aid.", "deadlines": "Fall: May 15. Spring: October 1.", "application_fee": "Not listed on the page.", "documents": "Application, transcripts, evaluation, English results, passport photo, sponsorship form. Estimated yearly cost shown is $21,610.", "fees_link": "https://centralstate.edu/international-student-admissions", "sources": ["https://centralstate.edu/international-student-admissions", "https://centralstate.edu/scholarships-and-employment-international-students"]}$q$::jsonb, admission_link = $q$https://centralstate.edu/international-student-admissions$q$, admission_checked = '2026-11-13' where id = '4b357058-fc01-440b-89cd-4ff50a265d0e' and country = 'United States';
update schools set admission_info = $q${"ug": "Official transcripts evaluated and translated by WES or SpanTran, a recommendation letter, and an essay. Fall entry only. After admission, send a Declaration of Finances and signed bank statements.", "english": "TOEFL iBT 79, IELTS 6.5, PTE 53, or Duolingo 110 (code 3506).", "how_to_apply": "Apply with the Common Application or ApplyMaine. All documents must arrive by the deadline or the file is not reviewed.", "deadlines": "June 1 for Fall.", "application_fee": "The page is titled Apply Free, but states no fee amount.", "documents": "Transcripts, recommendation, essay, English scores, then passport copy, I-20 or DS-2019 papers, bank statements, immunization proof, and health insurance. Required funds for 2025 to 2026: $37,435.", "fees_link": "https://farmington.edu/admissions-aid/international-students/", "sources": ["https://farmington.edu/admissions-aid/international-students/"]}$q$::jsonb, admission_link = $q$https://farmington.edu/admissions-aid/international-students/$q$, admission_checked = '2026-11-13' where id = '4d41fdbd-b665-40cb-8a87-dbc930dab413' and country = 'United States';
update schools set admission_info = $q${"ug": "International applicants follow the same process as domestic students. SAT or ACT is optional for admission but mandatory to be considered for scholarships.", "pg": "Course-by-course evaluation with GPA from a NACES member, sent directly to USCA. Student copies are not accepted.", "english": "Regular admission: TOEFL iBT 80, IELTS 6.0, PTE 53, or Duolingo 105. Provisional: TOEFL iBT 61 to 79, IELTS 5.5, PTE 42 to 52, or Duolingo 95 to 100. Conditional admission is possible without scores if you meet other criteria.", "how_to_apply": "Apply online with the fee. F-1 students cannot get U.S. federal aid. The page lists no named scholarships for international students.", "deadlines": "Not listed on the page.", "application_fee": "$100, non-refundable.", "documents": "Official records with certified English translations, financial certification form with original bank documents for one year, and English proof.", "fees_link": "https://www.usca.edu/admissions/admission-types/international/", "sources": ["https://www.usca.edu/admissions/admission-types/international/", "https://www.usca.edu/admissions/admission-types/international/english-proficiency-requirements/"]}$q$::jsonb, admission_link = $q$https://www.usca.edu/admissions/admission-types/international/$q$, admission_checked = '2026-11-13' where id = '5824db3e-55f3-4a43-a427-55ece0f7f378' and country = 'United States';
update schools set admission_info = $q${"ug": "Apply through the SUNY Application or Common App. Transcripts need full professional English translation. First-year applicants show a college-preparatory program. Transfers need a course-by-course evaluation from an approved agency. Passport copy required.", "pg": "Bachelor's degree with about a B average in junior and senior years, resume, statement of goals, two recommendation letters (three for PhD), and GRE for some programs. Fellowships and assistantships are tied to the earlier funding deadlines.", "english": "Undergraduate: TOEFL iBT 79, IELTS 6.0 (writing 5), Duolingo 100, SAT reading and writing 500, or ACT 22. Graduate: TOEFL iBT 80 (no section under 17), IELTS 6.0, or Duolingo 105.", "how_to_apply": "Apply online. For the I-20, show first-year funds, pay the admissions deposit, and send the information form and passport. Undergraduate deadlines and fee are not on the page.", "deadlines": "Graduate PhD and MS: Fall funding date January 15, final April 30. Spring funding date November 1, final December 15. Undergraduate deadlines not listed.", "application_fee": "Graduate: $60 nonrefundable. Undergraduate: not listed.", "documents": "Translated transcripts, evaluation, passport, English proof, proof of one year of funds (bank letter in USD with statements, or official award letter).", "fees_link": "https://www.esf.edu/admissions/apply/international-students", "sources": ["https://www.esf.edu/admissions/apply/international-students", "https://www.esf.edu/graduate/prospective/admission.php"]}$q$::jsonb, admission_link = $q$https://www.esf.edu/admissions/apply/international-students$q$, admission_checked = '2026-11-13' where id = '7aa9db6c-d13f-4289-b6c9-6aed6a727116' and country = 'United States';
update schools set admission_info = $q${"ug": "Official secondary and college transcripts sent directly to admissions, with certified English translations. Optional recommendation letters, resume, or portfolio. After admission, complete financial certification, send a bank statement and passport copy for your I-20.", "english": "Duolingo 105, IELTS 5.5, TOEFL iBT 79 (tests after January 21, 2026), PTE 53, SAT reading and writing 540, or ACT 21 in English and Reading. Waived for first-language English speakers from listed countries.", "how_to_apply": "Apply online. A $175 nonrefundable confirmation fee saves your place after admission. The page does not state whether international students can get the general scholarships.", "deadlines": "Fall: priority May 1, deposit by June 15. Spring: November 1, deposit by December 15.", "application_fee": "$30, cannot be waived.", "documents": "Transcripts with translation, English score report, financial certification, bank statement, passport copy.", "fees_link": "https://morris.umn.edu/admissions/apply/apply-international-student", "sources": ["https://morris.umn.edu/admissions/apply/apply-international-student", "https://morris.umn.edu/admissions/apply/apply-international-student/english-language-proficiency"]}$q$::jsonb, admission_link = $q$https://morris.umn.edu/admissions/apply/apply-international-student$q$, admission_checked = '2026-11-13' where id = 'a1fe35f6-94e8-426b-bd67-f1a87cbfc568' and country = 'United States';
update schools set admission_info = $q${"ug": "Secondary school graduation with a C average or better. Non-U.S. transcripts need a NACES course-by-course evaluation. Statement of purpose, financial affidavit with bank statements for two semesters, signed FERPA form, MMR records, and passport copy.", "pg": "Each graduate program has its own application. Send admission documents to the department. After admission send passport copy, Financial Affidavit of Support, FERPA form, and MMR record to the international office.", "english": "Any one of: TOEFL iBT 61, IELTS 5.5, PTE 44, Duolingo 90, SAT 940, ACT 18, or WASSCE English grade C or better. Graduate minimums are not stated.", "how_to_apply": "Apply online. Applications are processed on a rolling basis. Scholarship amounts are set after your academic review.", "deadlines": "No dates listed. Rolling admission.", "application_fee": "$20 for undergraduates. Graduate fee not listed.", "documents": "Translated transcripts, English proof, statement of purpose, financial affidavit, FERPA form, MMR record, passport copy.", "fees_link": "https://wvstateu.edu/admissions/international-student-admissions/international-undergraduate-student-admissions/", "sources": ["https://wvstateu.edu/admissions/international-student-admissions/international-undergraduate-student-admissions/", "https://wvstateu.edu/?p=32281", "https://wvstateu.edu/wp-content/uploads/2024/08/WVSU-English-Language-Proficiency-requirements-Undergradaute-Admissions.pdf"]}$q$::jsonb, admission_link = $q$https://wvstateu.edu/wp-content/uploads/2024/08/WVSU-English-Language-Proficiency-requirements-Undergradaute-Admissions.pdf$q$, admission_checked = '2026-11-13' where id = 'e4e349f0-2ad3-4144-a0af-1436240c3cf5' and country = 'United States';
update schools set admission_info = $q${"ug": "Passport copy, official secondary credentials with leaving exam results, a NACES course-by-course evaluation for college work, Declaration of Finance, and funds for a full year. International students pay the non-resident tuition rate.", "pg": "The page does not separate graduate rules. Check the Graduate Studies page.", "english": "TOEFL iBT 71 (3.5 on the new scale), IELTS 6.0, Duolingo 105, or PTE 51. Scores valid two years.", "how_to_apply": "Apply online and pay the fee. Processing into an I-20 takes about a month.", "deadlines": "Fall: July 1 (cut-off July 16). Spring: November 15 (cut-off December 1).", "application_fee": "$35, one-time.", "documents": "Passport copy, English scores, credentials and evaluation, Declaration of Finance, bank documents, immunization records.", "fees_link": "https://dickinsonstate.edu/admissions/international-students/", "sources": ["https://dickinsonstate.edu/admissions/international-students/", "https://dickinsonstate.edu/admissions/tuition-and-cost-to-attend/financial-aid/scholarships/"]}$q$::jsonb, admission_link = $q$https://dickinsonstate.edu/admissions/international-students/$q$, admission_checked = '2026-11-13' where id = 'f2485e20-9566-4717-b304-58e36158317a' and country = 'United States';
