update schools set admission_info = $q${"ug": "Cumulative GPA of 2.0 on the U.S. scale for freshmen and transfers. Transcripts translated into English (SpanTran recommended). For in-person study, the FSA-4 financial form with support documents and a color passport copy.", "english": "The page links to a separate English Proficiency Scores page and gives no scores.", "how_to_apply": "Apply online and send documents to International Admissions. The general scholarship page does not say whether international students qualify, so ask the scholarship office.", "deadlines": "Not listed on the page.", "application_fee": "Not listed on the page.", "documents": "Transcripts with translation, English scores, FSA-4 with support documents, and passport copy.", "fees_link": "https://canton.edu/admissions/international/requirements.html", "sources": ["https://canton.edu/admissions/international/requirements.html", "https://canton.edu/admissions/scholarships.html"]}$q$::jsonb, admission_link = $q$https://canton.edu/admissions/international/requirements.html$q$, admission_checked = '2026-11-13' where id = '12d9e22d-240b-4500-8468-fce986f18ed7' and country = 'United States';
update schools set admission_info = $q${"ug": "Online application, official transcripts with a credential evaluation (The Evaluation Company or other NACES member) showing GPA, English proof, financial proof dated within three months, and passport copy. Undergraduate funds needed: $27,768, which includes the $5,000 Experience Colorado Scholarship.", "pg": "Same documents as undergraduate. Funds vary by MBA or MS program, so email graduatestudies@adams.edu.", "english": "Undergraduate: Duolingo 90 or TOEFL iBT 61. Graduate: Duolingo 105 or TOEFL iBT 80. TOEFL scores must come from ETS (code 4001) and be under two years old. SAT reading and writing 470 or ACT English 18 also count.", "how_to_apply": "Complete the International Application for Admission. Admitted international first-year and transfer students get the Experience Colorado Scholarship.", "deadlines": "Fall: July 15. Spring: December 15. Summer (graduate only): April 15.", "application_fee": "$30, graduate applicants only.", "documents": "Transcripts and evaluation, English proof, financial verification, passport copy; optional essays and recommendation letters.", "fees_link": "https://www.adams.edu/admissions/international/requirements/", "sources": ["https://www.adams.edu/admissions/international/requirements/", "https://www.adams.edu/admissions/international/scholarships-financial-aid/"]}$q$::jsonb, admission_link = $q$https://www.adams.edu/admissions/international/requirements/$q$, admission_checked = '2026-11-13' where id = '2496ac7d-137e-40ae-b07b-4e0a0b612157' and country = 'United States';
update schools set admission_info = $q${"ug": "Official secondary records for grades 9 to 12 with required national exam results and literal English translations, plus an official transcript evaluation from a Pitt-approved service. Transfer applicants also send college transcripts and course catalogs or syllabi. SAT or ACT is sent if taken.", "english": "TOEFL, IELTS, or Duolingo results are required for most international applicants. The page gives no minimum scores.", "how_to_apply": "Apply online through the University of Pittsburgh portal. Send documents by email to admissions@upb.pitt.edu or by mail. The page does not mention scholarships for international students.", "deadlines": "Fall: June 15. Spring: October 15.", "application_fee": "None. The online application is free.", "documents": "Secondary records with translation, approved transcript evaluation, SAT or ACT if taken, and English test results.", "fees_link": "https://www.upb.pitt.edu/admissions-aid/international-students/application-requirement", "sources": ["https://www.upb.pitt.edu/admissions-aid/international-students/application-requirement"]}$q$::jsonb, admission_link = $q$https://www.upb.pitt.edu/admissions-aid/international-students/application-requirement$q$, admission_checked = '2026-11-13' where id = '3ebbf3b8-3b8d-4ffe-8c38-b9ab878a8322' and country = 'United States';
update schools set admission_info = $q${"ug": "Common Application or UMW Application with essay, official secondary records or exam results with certified English translation, and proof of funds for one year before the I-20 is issued. Transfers send transcripts from every college.", "pg": "The international checklist covers undergraduates only. Graduate programs listed include MBA, MSN, M.Ed., and MS in AI in Business. Check the graduate admissions pages.", "english": "IELTS 6.5, Duolingo 120, PTE 58, SAT reading and writing 500, ACT 22, or ILA Intensive English Level 12. The TOEFL line on the page is unclear. Waivers are possible for first-language English speakers or graduates of English-language secondary schools.", "how_to_apply": "Apply with the Common App or UMW application. Merit scholarships are automatic with admission, no separate form.", "deadlines": "First-year: priority January 1, regular February 1. Transfer: October 15 for Spring, April 1 for Fall.", "application_fee": "Required or fee waiver, but the amount is not stated.", "documents": "Transcripts with certified translation, English proof, bank letter or statement not older than three months in English, I-134 if a U.S. person supports you.", "fees_link": "https://www.umw.edu/admissions/international/checklist/", "sources": ["https://www.umw.edu/admissions/international/checklist/", "https://www.umw.edu/admissions/international/international-scholarships/"]}$q$::jsonb, admission_link = $q$https://www.umw.edu/admissions/international/checklist/$q$, admission_checked = '2026-11-13' where id = '6476090c-9472-4031-8d1b-c8502db97d2a' and country = 'United States';
update schools set admission_info = $q${"ug": "F-1 applicants must send extra documents to complete admission. The pages I could read do not list the specific documents or English minimums.", "how_to_apply": "Apply through the UNC Asheville admissions site and see the International Student Admissions page for details. All incoming first-year students are automatically considered for merit scholarships, but the page does not say if this covers international students.", "deadlines": "Fall: June 1. Spring: November 1. These are final dates for all materials.", "application_fee": "Standard fee not listed. The page says application fees are waived until November 13, 2026.", "fees_link": "https://www.unca.edu/admission/", "sources": ["https://www.unca.edu/admission/"]}$q$::jsonb, admission_link = $q$https://www.unca.edu/admission/$q$, admission_checked = '2026-11-13' where id = 'c90b91e0-b515-43b3-8694-517c97bbf386' and country = 'United States';
update schools set admission_info = $q${"ug": "High school GPA of at least 2.0 for freshmen, or a 2.0 college GPA for transfers (30 or more credits). Foreign transcripts need a course-by-course evaluation with GPA sent by the evaluation service. Immunization form and health insurance are required.", "pg": "Bachelor's degree equivalent with a course-by-course evaluation (WES preferred), program documents, and an affidavit of support. Show at least $25,000 per year in certified bank statements. MGA does not offer financial aid to international graduate students.", "english": "Proof is required if your first language is not English. The undergraduate page links to a list of accepted tests with no scores shown. Graduate applicants need official TOEFL scores, with no minimum listed.", "how_to_apply": "Apply online. For the I-20, send the affidavit of financial support and a bank letter showing $30,014 (undergraduate) or $29,052 (graduate).", "deadlines": "Undergraduate: Fall June 1 (documents July 1), Spring November 1 (December 1), Summer April 1 (May 1). Graduate dates not on the page.", "application_fee": "Undergraduate: not listed. Graduate: $40.", "documents": "Application, evaluated transcripts, English proof, immunization form, financial affidavit, bank letter within six months, and health insurance or waiver.", "fees_link": "https://www.mga.edu/international/prospective-students.php", "sources": ["https://www.mga.edu/international/prospective-students.php", "https://mga.smartcatalogiq.com/en/2025-2026/the-graduate-school-academic-catalog-2025-2026/graduate-admissions/international-applicant-admissions-requirements"]}$q$::jsonb, admission_link = $q$https://www.mga.edu/international/prospective-students.php$q$, admission_checked = '2026-11-13' where id = 'e8d79324-96b3-4976-9da6-d272ac773c90' and country = 'United States';
update schools set admission_info = $q${"ug": "Academic records evaluated for U.S. equivalency (InCred recommended), proof of funds, a financial certification statement with original bank documents, MMR and MenACWY vaccine proof, TB testing unless from a low-risk country, and passport copy.", "english": "TOEFL iBT 71, IELTS 6.0, PTE 47, Duolingo 105, or Cambridge 170. Scores older than two years are not accepted.", "how_to_apply": "Submit the undergraduate application, fee, and documents to Enrollment Services. An I-20 is issued only after all items are on file. The page lists no international scholarships.", "deadlines": "Not listed on the page.", "application_fee": "$35 USD, non-refundable.", "documents": "Application, evaluated records, English score, financial certification with bank documents, vaccine and TB records, passport copy, and $100 tuition deposit.", "fees_link": "https://www.vcsu.edu/admissions/application-process/international-students/", "sources": ["https://www.vcsu.edu/admissions/application-process/international-students/"]}$q$::jsonb, admission_link = $q$https://www.vcsu.edu/admissions/application-process/international-students/$q$, admission_checked = '2026-11-13' where id = '0fbb969f-9bb3-4239-9a60-2793a86424ae' and country = 'United States';
update schools set admission_info = $q${"ug": "Freshmen send high school and any college transcripts evaluated by an approved company, English proof, a Financial Declaration and Certification with bank statement, health records, and passport copy. Transfers (12 or more credits after high school) follow the same list.", "pg": "Bachelor's degree equivalent to a U.S. regionally accredited four-year degree. The only graduate degree open to on-campus international students is the MBA. Same documents as undergraduates.", "english": "TOEFL iBT 80, IELTS Academic 6.5, Duolingo 95, ACT English and Reading 19, SAT reading and writing 440, or 6 credit hours of English composition with a C or better. Waived for secondary study in English in listed countries, including Nigeria.", "how_to_apply": "Use the online international application. Apply early because visa processing takes time. The costs page names no scholarships made only for international students.", "deadlines": "Fall: July 15 (outside U.S. needing F-1) or August 17 (transferring in the U.S.). Spring: November 15 or January 2.", "application_fee": "Free to apply.", "documents": "Evaluated transcripts, English proof, Financial Declaration and bank statement, health services forms, unexpired passport copy.", "fees_link": "https://www.csc.edu/international/how-to-apply/", "sources": ["https://www.csc.edu/international/how-to-apply/", "https://www.csc.edu/international/how-to-apply/english-language-proficiency/", "https://www.csc.edu/international/costs--scholarships/"]}$q$::jsonb, admission_link = $q$https://www.csc.edu/international/how-to-apply/$q$, admission_checked = '2026-11-13' where id = '59ddc57e-5cfc-4554-913a-2b7c371a9a73' and country = 'United States';
update schools set admission_info = $q${"ug": "Common App or SMCM application with essay and supplement, official secondary and college transcripts sent by the school, school report, and teacher recommendations. SAT or ACT is recommended but optional. Interview recommended.", "english": "Everyone must show English skills. TOEFL iBT above 90 (Reading 20, Listening 22, Speaking 20, Writing 24), IELTS above 6.5 with no band below 6.5, Duolingo 115, WIDA 5.0, or SAT reading and writing 550. Skipped after four years of English-language secondary school.", "how_to_apply": "Apply through the Common App or SMCM application. The page lists no scholarships for international students, only that SAT or ACT scores may help scholarship review.", "deadlines": "Early Decision I and Early Action: November 1. Early Decision II and Regular Decision: January 15.", "application_fee": "$50 (waived for fee waiver and first-generation applicants).", "documents": "Passport copy, Certification of Finances Form, official bank statement, transcripts, recommendations.", "fees_link": "https://www.smcm.edu/admissions/how-to-apply/international-students/", "sources": ["https://www.smcm.edu/admissions/how-to-apply/international-students/"]}$q$::jsonb, admission_link = $q$https://www.smcm.edu/admissions/how-to-apply/international-students/$q$, admission_checked = '2026-11-13' where id = 'fc8dc6f5-7de6-47fb-8d4c-66b7dd9adaa0' and country = 'United States';
update schools set admission_info = $q${"ug": "International applicants follow the same steps as other first-year or transfer applicants. Send official records from all secondary and college schools, in English or with a certified English translation. Send WAEC results or predicted results, and explain any education gap longer than 13 months.", "english": "Any one of these: TOEFL iBT (page lists a composite of 4.0, with 3.5 in each part), IELTS 6.0, Duolingo 85, PTE 45, iTEP 3.5, SAT reading and writing 470, ACT English 15 and Reading 18, or finishing an Intensive English Program.", "how_to_apply": "Apply online using the same application as other students. Write your name as it appears on your passport and give a physical mailing address (no P.O. boxes). The page does not list graduate rules, so contact Admissions for those.", "documents": "Official transcripts from all schools, WAEC or other exam results, English test proof, and any other documents Admissions asks for. Transfer students should use TEC (The Evaluation Company); WES and ECE are also accepted.", "fees_link": "https://concord.edu/admissions/international/admission-requirements", "sources": ["https://concord.edu/admissions/international/admission-requirements"]}$q$::jsonb, admission_link = $q$https://concord.edu/admissions/international/admission-requirements$q$, admission_checked = '2026-11-13' where id = 'f810cb90-f661-42e0-95aa-41bed70b42d9' and country = 'United States';
update schools set admission_info = $q${"ug": "First-year applicants send an official high school transcript (grades 9 to 12) and results of any secondary leaving exam needed for university entry, such as WAEC or A levels. SAT and ACT scores are not required for international applicants.", "english": "TOEFL, IELTS or another approved English test is required, unless you are from an exempt country. Scores must be sent directly by the testing agency.", "how_to_apply": "Apply with the Golden Eagle Application and pay the fee. After admission, show funds for one full year before an I-20 is issued. International students pay the same tuition as everyone else (no out-of-state rate). The page lists no separate international scholarship.", "deadlines": "Spring 2027: November 1, 2026. Fall 2027: June 1, 2027.", "application_fee": "$30. A fee waiver is available for students with limited means.", "documents": "Application, $30 fee, official high school transcript with English translation, WAEC or other leaving exam results, English test scores. For the I-20: passport copy, International Student Agreement, Certification of Finances, and Declaration of Support with bank documents.", "fees_link": "https://crk.umn.edu/admissions/application", "sources": ["https://crk.umn.edu/admissions/application"]}$q$::jsonb, admission_link = $q$https://crk.umn.edu/admissions/application$q$, admission_checked = '2026-11-13' where id = '0064ecec-8593-4387-af01-835419566f48' and country = 'United States';
update schools set admission_info = $q${"ug": "First-year applicants send the Common Application, a letter of recommendation and a personal statement. Transcripts from outside the U.S. need a course-by-course evaluation from an approved service (TEC, Scholaro, CED, WES or ECE).", "english": "If English is not your first language: Duolingo 100, TOEFL iBT 79 (or 550 paper), IELTS 6.0, PTE 50, or LanguageCert B2 score of 33. A waiver may be possible if you studied in English.", "how_to_apply": "Apply through the Common Application. A Certification of Finances is needed before MCLA issues the I-20. The page says students on student visas are not eligible for merit scholarships or U.S. federal aid, but may qualify for a waiver covering on-campus living costs.", "deadlines": "Fall: March 1. Spring: November 15.", "application_fee": "Not stated on the page.", "documents": "Common Application, recommendation letter, personal statement, evaluated transcripts, English test scores, Certification of Finances.", "fees_link": "https://mcla.edu/admission-aid/undergraduate-admission/international-students.php", "sources": ["https://mcla.edu/admission-aid/undergraduate-admission/international-students.php"]}$q$::jsonb, admission_link = $q$https://mcla.edu/admission-aid/undergraduate-admission/international-students.php$q$, admission_checked = '2026-11-13' where id = '3b9da11f-aee1-47bf-af00-abe656d77ab1' and country = 'United States';
update schools set admission_info = $q${"ug": "Meet one of these: a GPA equal to 2.60 on a 4.0 scale, or ACT 18 or SAT 950 (with at least 480 Math and 450 Critical Reading). Transcripts must be official, with certified English translations. If not in English, have them evaluated by ECE or WES.", "pg": "A four-year bachelor degree equal to a U.S. one, possibly with a transcript evaluation, and the minimum GPA set by your program.", "english": "Undergraduate: TOEFL iBT 71 (tests before January 21, 2026) or 4.0 with no part under 3.5 (after), IELTS 6.0 with no part under 5.5, PTE 58, Duolingo 105, or WAEC English B3 or higher. Graduate: TOEFL iBT 76 (before January 21, 2026) or 4.0 with no part under 4.0 (after), IELTS 6.0, PTE 60, Duolingo 110, or WAEC English B3 or higher. Graduate scores must be within two years.", "how_to_apply": "Apply online through the DSU international admissions pages. Graduate applicants also fill in a Certificate of Financial Responsibility and must have approved health insurance. The pages did not list deadlines, fee or scholarships.", "documents": "Official transcripts (evaluated if needed), English test scores, and for graduate students a Certificate of Financial Responsibility and proof of health insurance.", "fees_link": "https://dsu.edu/ADMISSIONS/international/undergraduate/index.html", "sources": ["https://dsu.edu/ADMISSIONS/international/undergraduate/index.html", "https://dsu.edu/admissions/international/graduate/"]}$q$::jsonb, admission_link = $q$https://dsu.edu/ADMISSIONS/international/undergraduate/index.html$q$, admission_checked = '2026-11-13' where id = '32a8803f-0e00-4fd3-a970-21fe97d767ef' and country = 'United States';
update schools set admission_info = $q${"how_to_apply": "Freshman and transfer applicants apply through the CUNY online application. Transfer students already in the U.S. must send an I-20 Request Form with a transfer form, earlier I-20s, visa, passport, I-94 and financial documents to the Office of International Student Services. The page did not list English scores, fees, deadlines or scholarships.", "documents": "Credential evaluation from an agency such as WES or ECE is needed for foreign records. Transfer students need the I-20 Request Form, NYCCT Transfer Form, previous I-20s, visa, passport, I-94 and financial documents.", "fees_link": "https://citytech.cuny.edu/international/apply-now.aspx", "sources": ["https://citytech.cuny.edu/international/apply-now.aspx"]}$q$::jsonb, admission_link = $q$https://citytech.cuny.edu/international/apply-now.aspx$q$, admission_checked = '2026-11-13' where id = '95508e3e-8606-4148-b10f-07e82b2db891' and country = 'United States';
update schools set admission_info = $q${"ug": "Freshmen need a cumulative secondary GPA of 2.5 or better on a 4.0 scale. SAT or ACT is required for Engineering and Nursing. Engineering, Math and Chemistry need ACT math 19 or SAT math 510. Transfers need a 2.0 college GPA and 24 or more credit hours.", "english": "Required for admission: TOEFL iBT 79, IELTS 6.5, Duolingo 105, ACT English 24, SAT reading and writing 570, or PTE 53. Lower scores (TOEFL 61 to 78, IELTS 6.0 to 6.4, Duolingo 90 to 104) may admit you with English support courses.", "how_to_apply": "Apply through WVU Tech admissions. The I-20 is issued only after admission and financial papers are complete. Only F-1 visas are accepted. Academic or athletic scholarship amounts can be subtracted from the funds you must show.", "documents": "Academic records with English translation, diplomas, passport copy, and a WES basic evaluation with GPA for non-U.S. schools. Show funds for one full year in bank statements under 6 months old, in USD, plus a sponsor Declaration of Support form if needed.", "fees_link": "https://admissions.wvutech.edu/apply/intl-requirements", "sources": ["https://admissions.wvutech.edu/apply/intl-requirements"]}$q$::jsonb, admission_link = $q$https://admissions.wvutech.edu/apply/intl-requirements$q$, admission_checked = '2026-11-13' where id = 'a23b6fd3-6d26-4455-9fca-d404b37add61' and country = 'United States';
update schools set admission_info = $q${"ug": "Transcripts must be evaluated course by course, showing GPA, by a NACES-approved agency that sends the report directly to ECSU.", "english": "Any one of: a college English course with C or better, TOEFL 73, IELTS 6.0, Duolingo 90, or SAT reading 450.", "how_to_apply": "Apply at ecsu.edu/apply and pay the fee. Complete the Financial Guarantee Form and show a bank statement. You must arrive before the last day of registration. The page says international students cannot get federal aid and often do not qualify for scholarships at entry, so plan to pay the first year yourself. Departmental scholarships may come after the first year.", "deadlines": "Fall: May 1. Spring: October 1.", "application_fee": "$30, non-refundable.", "documents": "Passport ID page copy, International Student Data Form, Financial Guarantee Form, bank statement, and the credential evaluation. Upload PDF files only. The page gives two different proof-of-funds amounts ($30,000 and $19,234), so confirm with Admissions.", "fees_link": "https://ecsu.edu/admissions/international-students.php", "sources": ["https://ecsu.edu/admissions/international-students.php"]}$q$::jsonb, admission_link = $q$https://ecsu.edu/admissions/international-students.php$q$, admission_checked = '2026-11-13' where id = '3d324b94-9feb-4fda-99ef-fdf2ba0a8912' and country = 'United States';
update schools set admission_info = $q${"ug": "Apply as a first-year student through the Common Application with an essay. Send official SAT or ACT scores directly to CNU. A teacher evaluation, school counselor report and interview are recommended.", "english": "If English is not your native language you must send English proficiency scores. The page does not list accepted tests or minimum scores.", "how_to_apply": "Apply on the Common Application and pick Early Decision, Early Action or Regular Decision. Reviewed on a rolling basis. Only students who need an F-1 visa send the Financial Resources Statement and bank statements.", "deadlines": "Early Decision: November 15. Early Action: December 1. Regular Decision: February 1.", "application_fee": "$65 USD, non-refundable.", "documents": "Common Application with essay, official high school transcripts with English translation, official SAT or ACT scores, Financial Resources Statement with bank statements (if F-1 needed).", "fees_link": "https://cnu.edu/admission/international/freshman/howtoapply/", "sources": ["https://cnu.edu/admission/international/freshman/howtoapply/"]}$q$::jsonb, admission_link = $q$https://cnu.edu/admission/international/freshman/howtoapply/$q$, admission_checked = '2026-11-13' where id = '4cdbef23-90f8-4ae5-b06e-bfb6dfd1b82c' and country = 'United States';
update schools set admission_info = $q${"ug": "Freshman, transfer and exchange applicants send scanned official, translated transcripts from every school attended, plus a course-by-course evaluation from a NACES member such as WES or ECE.", "english": "IELTS 6.0 or above, TOEFL 67 or above, or Duolingo 100 or above. Scores must come directly from the testing organization.", "how_to_apply": "Apply through the UVA Wise portal and send the Supplemental Financial Guarantee Form. Transfers from another U.S. college also send an International Student Transfer Form. International Merit Scholarships exist for students with a minimum 3.2 GPA.", "deadlines": "Fall: May 1 (I-20 information by June 1). Spring: November 1 (I-20 information by November 15).", "application_fee": "Not stated on the page.", "documents": "Application, translated transcripts, credential evaluation, English test scores, financial guarantee form, transfer form if needed. Budget about $3,000 per year for books, supplies and health insurance.", "fees_link": "https://www.uvawise.edu/node/451", "sources": ["https://www.uvawise.edu/node/451"]}$q$::jsonb, admission_link = $q$https://www.uvawise.edu/node/451$q$, admission_checked = '2026-11-13' where id = 'd32b95f4-0bc9-45de-92f7-22813192cc9c' and country = 'United States';
update schools set admission_info = $q${"ug": "Show a minimum 2.0 GPA with original English transcripts and proof of high school graduation. Admission is by curriculum and is competitive.", "english": "TOEFL 500 paper or 61 iBT, IELTS 5.5, PTE 55, Duolingo 90, iTEP 4, GTEC CBT 1095, or LanguageCert B2 (60). The page gives slightly different minimums in two places, so confirm. Conditional admission is possible if English is short.", "how_to_apply": "Apply online through the SUNY application portal, or ask admissions@cobleskill.edu for a paper form. The page did not list the application fee or scholarships.", "deadlines": "Fall: preferred May 1. Spring: preferred October 15. TOEFL applicants: May 15 (fall) and October 15 (spring).", "documents": "Original English transcripts, official financial statement showing US funds for one year, English proof, passport photo page copy.", "fees_link": "https://cobleskill.edu/admissions/international-education/admissions-international.aspx", "sources": ["https://cobleskill.edu/admissions/international-education/admissions-international.aspx"]}$q$::jsonb, admission_link = $q$https://cobleskill.edu/admissions/international-education/admissions-international.aspx$q$, admission_checked = '2026-11-13' where id = '232f7190-304b-4deb-90e5-5bcd113c553d' and country = 'United States';
update schools set admission_info = $q${"ug": "Send official secondary school records for grades 9 to 11 plus national exam results, with literal English translations and an official transcript evaluation. SAT or ACT (code 2936 or 3733) is test-optional through Fall 2028 but strongly recommended.", "english": "For students from non-English countries: TOEFL 550 paper, 213 computer or 80 iBT. Official TOEFL or IELTS results may be sent; the page gives no IELTS score.", "how_to_apply": "Apply online and mail documents to the Office of Admissions in Greensburg, PA. An Attestation of Financial Support is needed for the I-20. The page did not list the fee or scholarships.", "deadlines": "Fall: April 1. Spring: November 1.", "documents": "Online application, evaluated school records with translations, SAT or ACT if sent, TOEFL or IELTS, and Attestation of Financial Support.", "fees_link": "https://www.greensburg.pitt.edu/admissions/apply-now/international-students", "sources": ["https://www.greensburg.pitt.edu/admissions/apply-now/international-students"]}$q$::jsonb, admission_link = $q$https://www.greensburg.pitt.edu/admissions/apply-now/international-students$q$, admission_checked = '2026-11-13' where id = '2af1634e-eabf-4ea4-afd2-8ccefda6f897' and country = 'United States';
update schools set admission_info = $q${"ug": "Send an official evaluation of all secondary and college transcripts from WES, InCred or SpanTran. ACT or SAT is optional.", "english": "Any one of: TOEFL 500 paper, 173 computer or 3.5 iBT; IELTS 5.5; PTE 44; or an approved Intensive English Program with the TOEFL or IELTS scores listed on the page.", "how_to_apply": "Apply online and send all documents by the deadline. The page lists no international scholarships and no application fee.", "deadlines": "May 1 for fall enrollment.", "documents": "Online application, transcript evaluation, certified bank statement showing the equal of $15,000 USD (under 3 months old), signed Affidavit of Financial Support, International Health Form signed by a physician, passport copy.", "fees_link": "https://usao.edu/future-students/international.html", "sources": ["https://usao.edu/future-students/international.html"]}$q$::jsonb, admission_link = $q$https://usao.edu/future-students/international.html$q$, admission_checked = '2026-11-13' where id = '6a91da34-48f3-460f-8a93-432b0ae079e8' and country = 'United States';
update schools set admission_info = $q${"ug": "Send an official transcript covering your last four years of study. You take a placement test on arrival.", "english": "TOEFL minimum of 70 overall with sub-scores of 17 or 18 for university-level courses. You may need ESL classes after the placement test.", "how_to_apply": "Apply at apply.utsouthern.edu, pay the fee, sign a statement of financial responsibility and send financial papers and a passport copy to the International Student Advisor. The page lists no scholarships and no deadline.", "application_fee": "$30 international application fee. After acceptance, F-1 students pay a $350 SEVIS I-901 fee.", "documents": "Official transcript, statement of financial responsibility, Required Financial Information form with financial documents, passport copy. Estimated yearly cost for sponsorship is $25,307.", "fees_link": "https://utsouthern.edu/international-students/", "sources": ["https://utsouthern.edu/international-students/"]}$q$::jsonb, admission_link = $q$https://utsouthern.edu/international-students/$q$, admission_checked = '2026-11-13' where id = '589ee54c-4aba-441b-9810-a80cddecf7db' and country = 'United States';
update schools set admission_info = $q${"ug": "Apply free to UMA. International students cannot enroll in fully online programs and need an F-1 visa for on-campus study. Foreign university records need a course-by-course evaluation sent directly to the University of Maine System.", "english": "TOEFL iBT 68 or IELTS 6.5. A SAT Verbal of 550 or ACT English of 24 (under 3 years old) also exempts you.", "how_to_apply": "Apply free online. Decisions come in 7 to 10 business days after the file is complete. You need to show at least $42,950 before an I-20 is issued. The page says non-citizens cannot get U.S. federal aid and lists no international scholarships.", "deadlines": "Certificate of Finances and passport due: Fall June 1, Spring November 1, Summer April 1.", "application_fee": "The application is described as free.", "documents": "Official transcripts or evaluation, Certificate of Finances, passport copy. Admitted students pay a $350 SEVIS fee.", "fees_link": "https://www.uma.edu/admission/international/", "sources": ["https://www.uma.edu/admission/international/"]}$q$::jsonb, admission_link = $q$https://www.uma.edu/admission/international/$q$, admission_checked = '2026-11-13' where id = 'a550cc20-c7d0-4d57-9b08-191e4d2caaea' and country = 'United States';
update schools set admission_info = $q${"how_to_apply": "The regional campus page defines an international student as one who does not live in the U.S. and sends applicants to the application portal. It does not list international requirements, English scores, fee or scholarships. Contact Admission@MiamiOH.edu.", "deadlines": "General deadlines: Spring January 5, Fall August 1, Nursing December 1.", "fees_link": "https://miamioh.edu/regionals/admission/apply/", "sources": ["https://miamioh.edu/regionals/admission/apply/"]}$q$::jsonb, admission_link = $q$https://miamioh.edu/regionals/admission/apply/$q$, admission_checked = '2026-11-13' where id = 'e979c838-3c07-4002-b975-7a75c2e59598' and country = 'United States';
update schools set admission_info = $q${"how_to_apply": "The regional campus page defines an international student as one who does not live in the U.S. and sends applicants to the application portal. It does not list international requirements, English scores, fee or scholarships. Contact Admission@MiamiOH.edu.", "deadlines": "General deadlines: Spring January 5, Fall August 1, Nursing December 1.", "fees_link": "https://miamioh.edu/regionals/admission/apply/", "sources": ["https://miamioh.edu/regionals/admission/apply/"]}$q$::jsonb, admission_link = $q$https://miamioh.edu/regionals/admission/apply/$q$, admission_checked = '2026-11-13' where id = 'c202fe47-6583-4dc4-9a90-43393cef296b' and country = 'United States';
update schools set admission_info = $q${"ug": "Send official high school and any college transcripts, translated and evaluated, plus SAT or ACT scores meeting the school minimums (not listed).", "english": "Non-native speakers send TOEFL or IELTS scores. The page does not list minimum scores.", "how_to_apply": "Apply as an international student needing an F-1 visa. The page lists no scholarships.", "deadlines": "Fall: May 1. Spring: September 15. Summer: February 1.", "application_fee": "$50", "documents": "Evaluated transcripts, immunization certificate, English proof, bank statement showing $25,000 USD on bank letterhead dated within 90 days, passport, local emergency contact and home country address.", "fees_link": "https://daltonstate.edu/admissions/international-student.cms", "sources": ["https://daltonstate.edu/admissions/international-student.cms"]}$q$::jsonb, admission_link = $q$https://daltonstate.edu/admissions/international-student.cms$q$, admission_checked = '2026-11-13' where id = '2cd6532e-b3c0-4ea3-a9ea-62912654c342' and country = 'United States';
update schools set admission_info = $q${"ug": "First-year: unweighted GPA of 2.0 or higher in college preparatory courses. Transfer: 2.0 or higher cumulative college GPA. Non-U.S. transcripts need a paid course-by-course evaluation, and your application is not complete without it. Test-optional essay is allowed instead of SAT or ACT.", "english": "TOEFL iBT 79 (550 paper, or 4 on the new TOEFL), IELTS 6, or Duolingo 105. First-year alternatives include ACT 24, SAT 1100, or B grades in all English courses with a school letter.", "how_to_apply": "Apply online or by paper with the fee. Deadlines are on a separate Quarterly Application Deadlines page. You must show funds for the full cost of attendance. The page lists no scholarships.", "application_fee": "$60 (waivers available through admissions@evergreen.edu).", "documents": "Application, fee, official transcripts, course-by-course evaluation of non-U.S. records, SAT or ACT or test-optional essay.", "fees_link": "https://www.evergreen.edu/offices-services/international-student-services/undergraduate-admissions", "sources": ["https://www.evergreen.edu/offices-services/international-student-services/undergraduate-admissions"]}$q$::jsonb, admission_link = $q$https://www.evergreen.edu/offices-services/international-student-services/undergraduate-admissions$q$, admission_checked = '2026-11-13' where id = '9cd2ae3e-4f55-4bdd-bd15-64e809a16d74' and country = 'United States';
update schools set admission_info = $q${"ug": "Apply through Common App or Apply Maine. Transcripts must be evaluated with GPA by a NACES or AICE service (InCred or WES recommended), at your cost. A final high school transcript is needed before the I-20.", "english": "TOEFL iBT 4 as listed since January 21, 2026 (previously 79; verify), paper 550, TOEFL Essentials 8.5, IELTS 6.5, PTE 53, Duolingo 105, or Cambridge C1 Advanced. English-medium schooling can also qualify.", "how_to_apply": "Apply, then send the I-20 request. The page lists no fee and no scholarships. A $50 tuition deposit is needed before you register.", "deadlines": "I-20 documents, non-Canadian freshmen: Spring November 15, Fall July 15.", "documents": "I-20 Request form, Financial Affidavit with proof of funds, passport copy, tuition deposit, immunization records for in-person students.", "fees_link": "https://www.umpi.edu/admissions/on-campus-international/", "sources": ["https://www.umpi.edu/admissions/on-campus-international/"]}$q$::jsonb, admission_link = $q$https://www.umpi.edu/admissions/on-campus-international/$q$, admission_checked = '2026-11-13' where id = 'df7dfc4f-8ef7-4607-b432-f034aaab55c9' and country = 'United States';
update schools set admission_info = $q${"ug": "Have previous academic records evaluated by WES, InCred or Spantran. Admission is given after MSU receives the evaluation. ACT or SAT is not required.", "english": "TOEFL 68 iBT or 523 paper, IELTS 6.0, or Duolingo (score not given).", "how_to_apply": "Submit the MSU application. The page links to a scholarship portal but gives no international scholarship details. All international students must have North Dakota university system health insurance (2026-27 annual premium $2,280).", "application_fee": "$35", "documents": "International Certificate of Finances verified by a bank letter, evaluated transcripts, passport copy, immunization form.", "fees_link": "https://mayvillestate.edu/future-students/international-canadian-students/", "sources": ["https://mayvillestate.edu/future-students/international-canadian-students/"]}$q$::jsonb, admission_link = $q$https://mayvillestate.edu/future-students/international-canadian-students/$q$, admission_checked = '2026-11-13' where id = '77593484-ebb6-424f-ab27-a1aae79fa702' and country = 'United States';
update schools set admission_info = $q${"ug": "Penn State's university-wide international page lists: online application through MyPennState or the Common App, official transcripts from the last three years, and proof of English. SAT and ACT are optional (test-optional). Non-English records need a certified line-by-line English translation.", "english": "TOEFL iBT 4.5 for tests taken after January 21, 2026 (80 before that date), IELTS Academic 6.5, Duolingo 120, SAT reading and writing 570, or ACT English 24. Other options include GCSE or GCE English grade A to C and IB English A score of 5. Scores must be under two years old.", "how_to_apply": "Apply online through MyPennState or the Common App and pick this campus. This page is Penn State's general international page, not specific to this campus. The pages read did not list deadlines, fee or scholarships, so check with the campus admissions office.", "fees_link": "https://psu.edu/resources/international-students/admission-requirements", "sources": ["https://psu.edu/resources/international-students/admission-requirements", "https://berks.psu.edu/admission/international-student-admissions"]}$q$::jsonb, admission_link = $q$https://psu.edu/resources/international-students/admission-requirements$q$, admission_checked = '2026-11-13' where id = '5e45d248-25d5-47d6-87bd-5a3d0d9ea775' and country = 'United States';
update schools set admission_info = $q${"ug": "Penn State's university-wide international page lists: online application through MyPennState or the Common App, official transcripts from the last three years, and proof of English. SAT and ACT are optional (test-optional). Non-English records need a certified line-by-line English translation.", "english": "TOEFL iBT 4.5 for tests taken after January 21, 2026 (80 before that date), IELTS Academic 6.5, Duolingo 120, SAT reading and writing 570, or ACT English 24. Other options include GCSE or GCE English grade A to C and IB English A score of 5. Scores must be under two years old.", "how_to_apply": "Apply online through MyPennState or the Common App and pick this campus. This page is Penn State's general international page, not specific to this campus. The pages read did not list deadlines, fee or scholarships, so check with the campus admissions office.", "fees_link": "https://psu.edu/resources/international-students/admission-requirements", "sources": ["https://psu.edu/resources/international-students/admission-requirements", "https://altoona.psu.edu/admission/applying/international-students"]}$q$::jsonb, admission_link = $q$https://psu.edu/resources/international-students/admission-requirements$q$, admission_checked = '2026-11-13' where id = 'be341b4a-f43f-4c70-b1ec-13a93de86734' and country = 'United States';
update schools set admission_info = $q${"ug": "Three years of math (Algebra I, Geometry, Algebra II), three years of science (two with labs), three years of social science, and two years of one foreign language. Send official high school transcripts with English translations. SAT or ACT is optional.", "pg": "A bachelor degree from a four-year institution. A three-year Indian degree is reviewed case by case if from an institution accredited at NAAC A-level with first class honors or higher.", "english": "Send official TOEFL or IELTS if English is not your first language. Graduate: TOEFL minimum 4.5 (it was 80 before January 2026) or IELTS 6.5. Master's applicants may instead hold a degree from a U.S. or English-medium university.", "how_to_apply": "Undergraduates apply with the Common App. Graduate applicants make an online account, apply and pay the non-refundable fee (amount not listed). The page lists no scholarship details.", "deadlines": "Undergraduate: Spring November 1; Fall Early Action November 15; Fall April 1. Graduate fall: advised to send all materials by June 1.", "documents": "Common App, official transcripts with English translation, optional recommendation letter, passport page copy, official English test scores.", "fees_link": "https://manchester.unh.edu/admissions/international-students", "sources": ["https://manchester.unh.edu/admissions/international-students"]}$q$::jsonb, admission_link = $q$https://manchester.unh.edu/admissions/international-students$q$, admission_checked = '2026-11-13' where id = '1464bc86-630f-41f8-819b-a92875da628e' and country = 'United States';
update schools set admission_info = $q${"ug": "Apply as an international freshman at cuny.edu/apply. Send official transcripts or certified copies from every secondary school and university attended, plus external exam results and school leaving certificates. A third-party credential evaluation is not required, because CUNY evaluates your records.", "english": "If English is not your native language or language of instruction: TOEFL iBT 52, computer-based 170, paper 470, or IELTS 5.5.", "how_to_apply": "Apply through the CUNY application with the processing fee. The page says students with F-1 visas are not eligible for U.S. federal or state financial aid and lists no international scholarships.", "deadlines": "Fall: February 1. Spring: October 1.", "application_fee": "$65 processing fee, paid online by card or by bank money order.", "documents": "Application, official or certified transcripts with English translation, exam results, leaving certificates.", "fees_link": "https://www.mec.cuny.edu/admissions/international-applicant/f-1-students/freshman-guide/", "sources": ["https://www.mec.cuny.edu/admissions/international-applicant/f-1-students/freshman-guide/"]}$q$::jsonb, admission_link = $q$https://www.mec.cuny.edu/admissions/international-applicant/f-1-students/freshman-guide/$q$, admission_checked = '2026-11-13' where id = 'ab243273-26d3-4dac-9258-0f4986ce5a03' and country = 'United States';
update schools set admission_info = $q${"ug": "Open to first-year, transfer and non-traditional international students. Send certified, translated secondary school transcripts. Schools outside the U.S. and Canada need an evaluation from ECE, which can take 8 to 12 weeks.", "english": "TOEFL 70 iBT or 525 paper, SAT Writing 440, or ACT combined English/Writing 18. Citizens of Australia, Canada, England, Ireland, New Zealand, Scotland and Wales are exempt.", "how_to_apply": "Complete the UMW application, pay the fee, send the supplemental international application, English proof, transcripts and Certification of Finances. After admission you receive an I-20 for the F-1 visa. Deadlines and scholarships are not listed on the page.", "application_fee": "$30, non-refundable, in U.S. currency.", "documents": "Supplemental international application, certified translated transcripts, Certification of Finances from a bank or sponsor, doctor-signed record of two MMR vaccine doses and a recent TB skin test.", "fees_link": "https://www.umwestern.edu/?p=1641", "sources": ["https://www.umwestern.edu/?p=1641"]}$q$::jsonb, admission_link = $q$https://www.umwestern.edu/?p=1641$q$, admission_checked = '2026-11-13' where id = '3da909c3-707a-48c7-b209-f1d5541e419d' and country = 'United States';
update schools set admission_info = $q${"ug": "Academic standard: at least a 2.0 high school GPA with ACT 18, or a 3.0 high school GPA with any ACT score. The page notes international requirements may vary. Required units include English 4, math 4, social studies 3, science 3, arts 1 and foreign language 2.", "english": "TOEFL or another approved English test is required. The page does not give a minimum score.", "how_to_apply": "Apply and pay the fee by phone with the cashier's office. ACT or SAT is optional and helps with class placement. The pages list no deadlines and no international scholarships.", "application_fee": "$100, non-refundable (waived for athletic recruits).", "documents": "Application, high school transcripts or leaving certificate, color passport copy, immunization records, six months of bank statements, sponsor letter of financial support.", "fees_link": "https://www.glenville.edu/international-admissions/requirements-admission-international-programs", "sources": ["https://www.glenville.edu/international-admissions/requirements-admission-international-programs"]}$q$::jsonb, admission_link = $q$https://www.glenville.edu/international-admissions/requirements-admission-international-programs$q$, admission_checked = '2026-11-13' where id = '25d89b92-dcca-4e36-9926-d4d2a49d61f5' and country = 'United States';
update schools set admission_info = $q${"ug": "Send a translated high school transcript and a course-by-course evaluated college transcript from a NACES evaluator (SpanTran recommended). If you have no ACT or SAT and no transfer credit, you take placement tests.", "english": "TOEFL 500 paper, 173 computer or 61 iBT; IELTS 5.5; PTE Academic 44; iTEP Academic 3.5; or a 12-week approved Intensive English Program. The page lists a few lower TOEFL scores that are unclear, so confirm with Admissions.", "how_to_apply": "Apply, send the I-20 packet and English proof. The page did not list the application fee or scholarships.", "deadlines": "Fall: July 1. Spring: November 15.", "documents": "Application, translated transcripts, evaluated college transcript, I-20 packet, English proof, passport, proof of housing, hepatitis B and MMR records. Pay the $200 SEVIS fee after getting the I-20.", "fees_link": "https://www.rsu.edu/admissions/international/how-to-apply", "sources": ["https://www.rsu.edu/admissions/international/how-to-apply"]}$q$::jsonb, admission_link = $q$https://www.rsu.edu/admissions/international/how-to-apply$q$, admission_checked = '2026-11-13' where id = 'b20e6524-0058-45ec-a731-fd0b369c2df6' and country = 'United States';
update schools set admission_info = $q${"ug": "First-year applicants send official records for the last three years of school (through a STARS Record) and proof of English. SAT or ACT is optional. Transfer applicants send official college transcripts and proof of English.", "pg": "Graduate study is applied for through the Penn State Graduate School. You need a four-year bachelor's degree or equal, official transcripts from every college attended, and English test scores.", "english": "Undergraduate: Duolingo 120, IELTS Academic 6.5, TOEFL iBT 80 (taken before 21 Jan 2026) or 4.5 on the new scale, SAT reading and writing 570, or ACT English 24. Graduate: TOEFL iBT 80 (4.5 new scale) or IELTS 6.5. Scores must be under 2 years old.", "how_to_apply": "Apply online through MyPennState or the Common App. Show you have enough money for the first year of out-of-state tuition and costs. No international student scholarship was confirmed on the official pages checked for this campus.", "deadlines": "Undergraduate early action deadline is November 1. After that, applications are reviewed on a rolling basis. International students have earlier final deadlines because of visa time; check the Penn State international deadlines page.", "application_fee": "Undergraduate: $75. Graduate: $85 for international degree applicants.", "documents": "STARS Record or official school records, proof of English, official transcripts (certified English translation if needed), passport name used consistently, proof of funds. Documents must be official or certified copies.", "fees_link": "https://www.psu.edu/resources/international-students/steps-to-apply", "sources": ["https://www.psu.edu/resources/international-students/admission-requirements", "https://www.psu.edu/resources/international-students/steps-to-apply", "https://www.psu.edu/resources/international-students/deadlines", "https://gradschool.psu.edu/graduate-admissions/how-to-apply/new-applicants/requirements-for-graduate-admission"]}$q$: