update schools set admission_info = $q${"ug": "First-year applicants send official records for the last three years of school (through a STARS Record) and proof of English. SAT or ACT is optional. Transfer applicants send official college transcripts and proof of English.", "pg": "Graduate study is applied for through the Penn State Graduate School. You need a four-year bachelor's degree or equal, official transcripts from every college attended, and English test scores.", "english": "Undergraduate: Duolingo 120, IELTS Academic 6.5, TOEFL iBT 80 (taken before 21 Jan 2026) or 4.5 on the new scale, SAT reading and writing 570, or ACT English 24. Graduate: TOEFL iBT 80 (4.5 new scale) or IELTS 6.5. Scores must be under 2 years old.", "how_to_apply": "Apply online through MyPennState or the Common App. Show you have enough money for the first year of out-of-state tuition and costs. Penn State Scranton says it cannot offer financial assistance to undergraduate students from other countries.", "deadlines": "Undergraduate early action deadline is November 1. After that, applications are reviewed on a rolling basis. International students have earlier final deadlines because of visa time; check the Penn State international deadlines page.", "application_fee": "Undergraduate: $75. Graduate: $85 for international degree applicants.", "documents": "STARS Record or official school records, proof of English, official transcripts (certified English translation if needed), passport name used consistently, proof of funds. Documents must be official or certified copies.", "fees_link": "https://www.psu.edu/resources/international-students/steps-to-apply", "sources": ["https://www.psu.edu/resources/international-students/admission-requirements", "https://www.psu.edu/resources/international-students/steps-to-apply", "https://www.psu.edu/resources/international-students/deadlines", "https://gradschool.psu.edu/graduate-admissions/how-to-apply/new-applicants/requirements-for-graduate-admission", "https://scranton.psu.edu/admission/international/financial-information"]}$q$::jsonb, admission_link = $q$https://www.psu.edu/resources/international-students/steps-to-apply$q$, admission_checked = '2026-11-13' where id = '403e7dd5-f927-41e5-9bf2-56412d77f59c' and country = 'United States';
