update schools set admission_info = $q${"ug": "Send the HSSU application, official high school transcripts in English with a letter from the school stating GPA and class rank, and college transcripts with course descriptions if you studied at college.", "english": "TOEFL is needed if English is not your first language: 61 internet-based (500 paper, 173 computer).", "how_to_apply": "Apply through HSSU and send all documents to the Office of Admissions. The I-20 is issued after the application, health form, transcripts, notarized support letter and money on deposit are received. The page is marked as revised in 2012, so confirm current amounts with admissions. No international scholarship was confirmed.", "deadlines": "International deadlines: Fall June 1, Summer April 1, Spring November 1.", "documents": "Notarized letter of financial support, proof of at least $14,561 per year, money on deposit of $4,305.76 for non-Missouri residents (amounts may be outdated), medical exam and immunizations.", "fees_link": "https://www.hssu.edu/ae/aefiles/2/INTERNChklstrev012CMrev.pdf", "sources": ["https://www.hssu.edu/ae/aefiles/2/INTERNChklstrev012CMrev.pdf"]}$q$::jsonb, admission_link = $q$https://www.hssu.edu/ae/aefiles/2/INTERNChklstrev012CMrev.pdf$q$, admission_checked = '2026-11-13' where id = 'b5c22bf2-d389-47f4-9a92-bb529278fd0d' and country = 'United States';
update schools set admission_info = $q${"ug": "Freshmen must have finished 12 years of school. Send official transcripts with a course-by-course evaluation from a NACES-approved company, with GPA, plus English test scores.", "english": "TOEFL 77, Duolingo 100, IELTS 6.0 or PTE 50. Some English-speaking countries and students who passed US college English 101 and 102 with a C are exempt.", "how_to_apply": "Apply as an international student at least 6 months before your start term. After admission, pay the enrollment deposit to get the I-20, then pay the SEVIS fee and apply for the F-1 visa. No international scholarship was listed on the page.", "deadlines": "Fall: June 1. Spring: November 1.", "documents": "Evaluated transcripts, English scores, Certificate of Support showing funds for the first year, immunization record, health insurance proof.", "fees_link": "https://www.uscb.edu/admissions/apply/international-students/index.html", "sources": ["https://www.uscb.edu/admissions/apply/international-students/index.html"]}$q$::jsonb, admission_link = $q$https://www.uscb.edu/admissions/apply/international-students/index.html$q$, admission_checked = '2026-11-13' where id = 'c504d833-234e-4737-887f-b81378ead2fb' and country = 'United States';
update schools set admission_info = $q${"ug": "Send the online international application, official high school transcripts, and a credential evaluation of any college work from a NACES-affiliated company. Passport copy and a recommendation from an instructor, coach or employer are also needed.", "english": "PTE 50, TOEFL internet-based 64 (paper 500), IELTS 6.0 or Duolingo 90. The page notes the new TOEFL scale from January 2026. An ESL program is also accepted.", "how_to_apply": "Apply online and complete Accuplacer testing for placement after admission. The page states that financial aid is generally not available to international students.", "deadlines": "Fall: June 1. Spring: November 1. Applications must be complete one month after these dates.", "documents": "Passport copy, Financial Verification Form showing $33,700 per year, transcripts, evaluation, recommendation, proof of medical insurance on arrival.", "fees_link": "https://bluefieldstate.edu/international-student-services/", "sources": ["https://bluefieldstate.edu/international-student-services/"]}$q$::jsonb, admission_link = $q$https://bluefieldstate.edu/international-student-services/$q$, admission_checked = '2026-11-13' where id = '7fea0066-9085-4b89-a808-352fb85b4896' and country = 'United States';
update schools set admission_info = $q${"ug": "Apply through the Common App and send official high school or college transcripts. A NACES course-by-course evaluation may be needed.", "english": "One of: TOEFL iBT 79, IELTS 6.0, ACT English 21 or SAT reading and writing 500.", "how_to_apply": "Apply through the Common App, send financial proof, pay the Advance Registration Deposit and then receive the I-20. Pay the $350 SEVIS fee before the visa interview. Scholarships were not stated on the page.", "documents": "Notarized bank statement (stated minimum $30,762, may change) and an Affidavit of Support, evaluated transcripts.", "fees_link": "https://cheyney.edu/admissions/international-admissions", "sources": ["https://cheyney.edu/admissions/international-admissions"]}$q$::jsonb, admission_link = $q$https://cheyney.edu/admissions/international-admissions$q$, admission_checked = '2026-11-13' where id = '8235670f-755f-45d2-922c-5df1413d729f' and country = 'United States';
update schools set admission_info = $q${"ug": "Apply with the Common Application. Send a high school transcript, a recommendation from a counselor or school official, and an official evaluation of non-US records from a NACES member.", "english": "TOEFL 80 internet-based (550 paper), or IELTS Academic 6.5. SAT or ACT may replace these only with approval of the enrollment office. Some waivers apply.", "how_to_apply": "Apply through the Common App and submit a Financial Statement of Ability to Pay. International students cannot get federal aid but may receive institutional merit aid.", "deadlines": "Early Action: November 30. Regular Decision: March 1.", "application_fee": "$50", "documents": "Common App, transcript, recommendation, evaluation of non-US records, TOEFL or IELTS, Financial Statement of Ability to Pay.", "fees_link": "https://mainemaritime.edu/undergraduate-catalog/admissions/", "sources": ["https://mainemaritime.edu/undergraduate-catalog/admissions/"]}$q$::jsonb, admission_link = $q$https://mainemaritime.edu/undergraduate-catalog/admissions/$q$, admission_checked = '2026-11-13' where id = 'c5936af1-8bb2-42f8-a9f2-c3cf9f40ff3b' and country = 'United States';
update schools set admission_info = $q${"ug": "Charter Oak is an online, non-residential college. It does not issue the I-20 form needed for a student visa. International records must be evaluated by a NACES agency such as ECE or WES.", "english": "No test minimum listed. English composition credit from approved English-speaking countries with a C or better can meet the writing requirement.", "how_to_apply": "Apply online. Applicants outside the US must complete a notarized Identity Verification form. Because no I-20 is issued, this college is not suited for students who need an F-1 visa.", "documents": "Course-by-course credential evaluation, notarized identity verification form.", "fees_link": "https://www.charteroak.edu/catalog/current/ug_admissions/ug_international_students.php", "sources": ["https://www.charteroak.edu/catalog/current/ug_admissions/ug_international_students.php"]}$q$::jsonb, admission_link = $q$https://www.charteroak.edu/catalog/current/ug_admissions/ug_international_students.php$q$, admission_checked = '2026-11-13' where id = '5b552628-d71c-4421-b6d5-35f22e60ab33' and country = 'United States';
