update schools set admission_info = $q${"ug": "First-year: international application, official transcripts evaluated by an approved agency (WES, AES, ACEI, Josef Silny or TEC), and SAT, ACT or CLT scores.", "pg": "Graduate: international application, course-by-course evaluation, two recommendation letters, a statement of purpose, and English proof. Funds of $43,961 must be shown.", "english": "Send at least one of TOEFL, IELTS or MELAB. No minimum score is published. A waiver applies for degrees from US or English-language institutions.", "how_to_apply": "Apply online at the Florida Poly website. Show funds of $40,282 per year for undergraduates. Merit scholarships are awarded by GPA and test scores. F-1 students cannot get federal aid.", "deadlines": "Fall: Early Action November 15, Regular Decision March 1 (confirm). Spring: November 1.", "documents": "Passport copy, financial evidence, I-20 application form, immunization forms, health insurance, evaluated transcripts. Enrollment deposit $235.", "fees_link": "https://floridapoly.edu/admissions/international/", "sources": ["https://floridapoly.edu/admissions/international/"]}$q$::jsonb, admission_link = $q$https://floridapoly.edu/admissions/international/$q$, admission_checked = '2026-11-13' where id = 'ee31c18b-92ff-4d1f-8e48-c20c69ba30df' and country = 'United States';
